CREATE   TRIGGER finance.TR_CollectionFollowUp_Reminder ON finance.CollectionFollowUp AFTER INSERT AS BEGIN SET NOCOUNT ON;INSERT finance.PaymentReminder(PartyType,PartyId,ReferenceId,ReminderDate,ReminderNotes,CreatedBy,CreatedOn)SELECT 'CUSTOMER',CustomerId,InvoiceId,NextFollowUpDate,Notes,CreatedBy,SYSUTCDATETIME()FROM inserted WHERE NextFollowUpDate IS NOT NULL;END
GO
PRINT N'Creating Procedure [dashboard].[Summary_Get]...';


GO
CREATE   PROCEDURE dashboard.Summary_Get @From datetimeoffset,@To datetimeoffset AS BEGIN SET NOCOUNT ON;SELECT ISNULL((SELECT SUM(GrandTotal)FROM sales.SalesInvoices WHERE InvoiceDate>=@From AND InvoiceDate<@To AND Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')),0)TodaySales,ISNULL((SELECT SUM(GrandTotal)FROM purchase.PurchaseInvoices WHERE InvoiceDate>=@From AND InvoiceDate<@To AND IsDeleted=0 AND Status NOT IN('DRAFT','CANCELLED')),0)TodayPurchase,ISNULL((SELECT SUM(p.Amount)FROM sales.SalesPayments p JOIN sales.PaymentMethods m ON m.PaymentMethodId=p.PaymentMethodId WHERE p.PaymentDate>=@From AND p.PaymentDate<@To AND p.Status='COMPLETED'AND m.MethodCode='CASH'),0)CashCollection,ISNULL((SELECT SUM(p.Amount)FROM sales.SalesPayments p JOIN sales.PaymentMethods m ON m.PaymentMethodId=p.PaymentMethodId WHERE p.PaymentDate>=@From AND p.PaymentDate<@To AND p.Status='COMPLETED'AND m.MethodCode='UPI'),0)UpiCollection,ISNULL((SELECT SUM(p.Amount)FROM sales.SalesPayments p JOIN sales.PaymentMethods m ON m.PaymentMethodId=p.PaymentMethodId WHERE p.PaymentDate>=@From AND p.PaymentDate<@To AND p.Status='COMPLETED'AND m.MethodCode='CARD'),0)CardCollection,ISNULL((SELECT SUM((i.Quantity-i.ReturnedQuantity)*(i.UnitPrice-pr.PurchasePrice)-i.DiscountAmount)FROM sales.SalesInvoiceItems i JOIN sales.SalesInvoices h ON h.InvoiceId=i.InvoiceId JOIN master.Products pr ON pr.ProductId=i.ProductId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')),0)TodayProfit,ISNULL((SELECT SUM(e.Amount)FROM purchase.PurchaseExpenses e JOIN purchase.PurchaseInvoices h ON h.PurchaseInvoiceId=e.PurchaseInvoiceId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.IsDeleted=0),0)TodayExpense,ISNULL((SELECT SUM(p.Amount)FROM sales.SalesPayments p WHERE p.PaymentDate>=@From AND p.PaymentDate<@To AND p.Status='COMPLETED'),0)-ISNULL((SELECT SUM(p.Amount)FROM purchase.PurchasePayments p WHERE p.PaymentDate>=@From AND p.PaymentDate<@To AND p.Status='COMPLETED'),0)NetCollection;SELECT TOP(10)InvoiceId,InvoiceNumber,InvoiceDate,GrandTotal,Status FROM sales.SalesInvoices WHERE InvoiceDate>=@From AND InvoiceDate<@To ORDER BY InvoiceDate DESC;SELECT TOP(10)PurchaseInvoiceId,InvoiceNumber,InvoiceDate,GrandTotal,Status FROM purchase.PurchaseInvoices WHERE InvoiceDate>=@From AND InvoiceDate<@To AND IsDeleted=0 ORDER BY InvoiceDate DESC;END
GO
PRINT N'Creating Procedure [dashboard].[Purchase_Get]...';


GO
CREATE   PROCEDURE dashboard.Purchase_Get @From datetimeoffset,@To datetimeoffset AS BEGIN SET NOCOUNT ON;SELECT CONVERT(varchar(10),CONVERT(date,InvoiceDate),23)Label,SUM(GrandTotal)Value FROM purchase.PurchaseInvoices WHERE InvoiceDate>=@From AND InvoiceDate<@To AND IsDeleted=0 AND Status NOT IN('DRAFT','CANCELLED')GROUP BY CONVERT(date,InvoiceDate)ORDER BY CONVERT(date,InvoiceDate);SELECT CONCAT(YEAR(InvoiceDate),'-',RIGHT('0'+CONVERT(varchar(2),MONTH(InvoiceDate)),2))Label,SUM(GrandTotal)Value FROM purchase.PurchaseInvoices WHERE InvoiceDate>=DATEADD(month,-12,@To)AND InvoiceDate<@To AND IsDeleted=0 AND Status NOT IN('DRAFT','CANCELLED')GROUP BY YEAR(InvoiceDate),MONTH(InvoiceDate)ORDER BY YEAR(InvoiceDate),MONTH(InvoiceDate);SELECT s.SupplierName Label,SUM(i.GrandTotal)Value FROM purchase.PurchaseInvoices i JOIN purchase.Suppliers s ON s.SupplierId=i.SupplierId WHERE i.InvoiceDate>=@From AND i.InvoiceDate<@To AND i.IsDeleted=0 AND i.Status NOT IN('DRAFT','CANCELLED')GROUP BY s.SupplierName ORDER BY Value DESC;END
GO
