CREATE   PROCEDURE dashboard.Finance_Get @From datetimeoffset,@To datetimeoffset AS BEGIN SET NOCOUNT ON;EXEC finance.RefreshOutstanding;SELECT ISNULL((SELECT SUM(AmountIn-AmountOut)FROM finance.CashBook),0)CashBalance,ISNULL((SELECT SUM(AmountIn-AmountOut)FROM finance.BankBook),0)BankBalance,ISNULL((SELECT SUM(OutstandingAmount)FROM finance.CustomerOutstanding WHERE OutstandingAmount>0),0)Receivables,ISNULL((SELECT SUM(OutstandingAmount)FROM finance.SupplierOutstanding WHERE OutstandingAmount>0),0)Payables,ISNULL((SELECT SUM((i.Quantity-i.ReturnedQuantity)*(i.UnitPrice-p.PurchasePrice)-i.DiscountAmount)FROM sales.SalesInvoiceItems i JOIN sales.SalesInvoices h ON h.InvoiceId=i.InvoiceId JOIN master.Products p ON p.ProductId=i.ProductId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')),0)-ISNULL((SELECT SUM(e.Amount)FROM purchase.PurchaseExpenses e JOIN purchase.PurchaseInvoices h ON h.PurchaseInvoiceId=e.PurchaseInvoiceId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To),0)ProfitToday;END
GO
