CREATE   PROCEDURE dashboard.Suppliers_Get @From datetimeoffset,@To datetimeoffset AS BEGIN SET NOCOUNT ON;EXEC finance.RefreshOutstanding;SELECT ISNULL((SELECT SUM(OutstandingAmount)FROM finance.SupplierOutstanding WHERE OutstandingAmount>0),0)SupplierOutstanding,(SELECT COUNT(*)FROM finance.SupplierOutstanding WHERE OutstandingAmount>0)PendingPayments;SELECT TOP(10)s.SupplierName Label,SUM(i.GrandTotal)Value FROM purchase.Suppliers s JOIN purchase.PurchaseInvoices i ON i.SupplierId=s.SupplierId WHERE i.InvoiceDate>=@From AND i.InvoiceDate<@To AND i.IsDeleted=0 AND i.Status NOT IN('DRAFT','CANCELLED')GROUP BY s.SupplierName ORDER BY Value DESC;END
GO
