GO
CREATE   PROCEDURE dashboard.Sales_Get @From datetimeoffset,@To datetimeoffset AS BEGIN SET NOCOUNT ON;SELECT CONVERT(varchar(2),DATEPART(hour,InvoiceDate))Label,SUM(GrandTotal)Value FROM sales.SalesInvoices WHERE InvoiceDate>=@From AND InvoiceDate<@To AND Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY DATEPART(hour,InvoiceDate)ORDER BY DATEPART(hour,InvoiceDate);SELECT CONVERT(varchar(10),CONVERT(date,InvoiceDate),23)Label,SUM(GrandTotal)Value FROM sales.SalesInvoices WHERE InvoiceDate>=@From AND InvoiceDate<@To AND Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY CONVERT(date,InvoiceDate)ORDER BY CONVERT(date,InvoiceDate);SELECT CONCAT(YEAR(InvoiceDate),'-',RIGHT('0'+CONVERT(varchar(2),MONTH(InvoiceDate)),2))Label,SUM(GrandTotal)Value FROM sales.SalesInvoices WHERE InvoiceDate>=DATEADD(month,-12,@To)AND InvoiceDate<@To AND Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY YEAR(InvoiceDate),MONTH(InvoiceDate)ORDER BY YEAR(InvoiceDate),MONTH(InvoiceDate);SELECT CONVERT(varchar(4),YEAR(InvoiceDate))Label,SUM(GrandTotal)Value FROM sales.SalesInvoices WHERE Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY YEAR(InvoiceDate)ORDER BY Label;SELECT c.CategoryName Label,SUM(i.LineTotal)Value FROM sales.SalesInvoices h JOIN sales.SalesInvoiceItems i ON i.InvoiceId=h.InvoiceId JOIN master.Products p ON p.ProductId=i.ProductId JOIN master.ProductCategories c ON c.ProductCategoryId=p.CategoryId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY c.CategoryName ORDER BY Value DESC;SELECT b.BrandName Label,SUM(i.LineTotal)Value FROM sales.SalesInvoices h JOIN sales.SalesInvoiceItems i ON i.InvoiceId=h.InvoiceId JOIN master.Products p ON p.ProductId=i.ProductId JOIN master.Brands b ON b.BrandId=p.BrandId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY b.BrandName ORDER BY Value DESC;SELECT m.MethodName Label,SUM(p.Amount)Value FROM sales.SalesPayments p JOIN sales.PaymentMethods m ON m.PaymentMethodId=p.PaymentMethodId WHERE p.PaymentDate>=@From AND p.PaymentDate<@To AND p.Status='COMPLETED'GROUP BY m.MethodName ORDER BY Value DESC;SELECT TOP(10)p.ProductCode Label,SUM(i.Quantity-i.ReturnedQuantity)Value FROM sales.SalesInvoices h JOIN sales.SalesInvoiceItems i ON i.InvoiceId=h.InvoiceId JOIN master.Products p ON p.ProductId=i.ProductId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY p.ProductCode ORDER BY Value DESC;SELECT TOP(10)p.ProductCode Label,SUM(i.Quantity-i.ReturnedQuantity)Value FROM sales.SalesInvoices h JOIN sales.SalesInvoiceItems i ON i.InvoiceId=h.InvoiceId JOIN master.Products p ON p.ProductId=i.ProductId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY p.ProductCode ORDER BY Value ASC;SELECT TOP(10)p.ProductCode Label,SUM((i.Quantity-i.ReturnedQuantity)*(i.UnitPrice-p.PurchasePrice)-i.DiscountAmount)Value FROM sales.SalesInvoices h JOIN sales.SalesInvoiceItems i ON i.InvoiceId=h.InvoiceId JOIN master.Products p ON p.ProductId=i.ProductId WHERE h.InvoiceDate>=@From AND h.InvoiceDate<@To AND h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY p.ProductCode ORDER BY Value DESC;END
GO
