CREATE   PROCEDURE dashboard.Customers_Get @From datetimeoffset,@To datetimeoffset AS BEGIN SET NOCOUNT ON;EXEC finance.RefreshOutstanding;SELECT (SELECT COUNT(*)FROM sales.Customers WHERE CreatedOn>=@From AND CreatedOn<@To AND IsDeleted=0)NewCustomers,ISNULL((SELECT SUM(OutstandingAmount)FROM finance.CustomerOutstanding WHERE OutstandingAmount>0),0)CustomerOutstanding,(SELECT COUNT(*)FROM sales.Customers c WHERE c.IsDeleted=0 AND NOT EXISTS(SELECT 1 FROM sales.SalesInvoices i WHERE i.CustomerId=c.CustomerId AND i.InvoiceDate>=DATEADD(day,-90,@To)))InactiveCustomers;SELECT TOP(10)c.CustomerName Label,SUM(i.GrandTotal)Value FROM sales.Customers c JOIN sales.SalesInvoices i ON i.CustomerId=c.CustomerId WHERE i.InvoiceDate>=@From AND i.InvoiceDate<@To AND i.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')GROUP BY c.CustomerName ORDER BY Value DESC;END
GO
