GO
CREATE   PROCEDURE gst.SyncTransactions AS BEGIN SET NOCOUNT ON;DECLARE @state char(2)=(SELECT TOP(1)StateCode FROM gst.GSTSettings WHERE IsActive=1 ORDER BY EffectiveDate DESC);MERGE gst.GSTTransactions t USING(SELECT 'SALE'SourceType,h.InvoiceId SourceId,i.InvoiceItemId SourceLineId,h.InvoiceNumber DocumentNumber,h.InvoiceDate DocumentDate,h.CustomerId PartyId,c.CustomerName PartyName,c.GSTIN PartyGSTIN,h.WarehouseId,i.ProductId,p.HSNCode,p.SACCode,i.TaxPercentage GSTRate,(i.Quantity-i.ReturnedQuantity)Quantity,ROUND((i.Quantity-i.ReturnedQuantity)*i.UnitPrice-i.DiscountAmount,2)TaxableAmount,CASE WHEN LEFT(ISNULL(c.GSTIN,@state),2)=@state THEN ROUND(i.TaxAmount/2,2)ELSE 0 END CGSTAmount,CASE WHEN LEFT(ISNULL(c.GSTIN,@state),2)=@state THEN i.TaxAmount-ROUND(i.TaxAmount/2,2)ELSE 0 END SGSTAmount,CASE WHEN LEFT(ISNULL(c.GSTIN,@state),2)<>@state THEN i.TaxAmount ELSE 0 END IGSTAmount,CAST(0 AS decimal(18,2))CessAmount,h.RoundOff,CONVERT(bit,CASE WHEN c.GSTIN IS NOT NULL THEN 1 ELSE 0 END)IsB2B,LEFT(ISNULL(c.GSTIN,@state),2)PlaceOfSupply FROM sales.SalesInvoices h JOIN sales.SalesInvoiceItems i ON i.InvoiceId=h.InvoiceId JOIN master.Products p ON p.ProductId=i.ProductId LEFT JOIN sales.Customers c ON c.CustomerId=h.CustomerId WHERE h.Status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED')UNION ALL SELECT'PURCHASE',h.PurchaseInvoiceId,i.PurchaseItemId,h.InvoiceNumber,h.InvoiceDate,h.SupplierId,s.SupplierName,s.GSTIN,h.WarehouseId,i.ProductId,p.HSNCode,p.SACCode,i.GSTPercentage,i.Quantity+i.FreeQuantity-i.ReturnedQuantity,ROUND(i.Quantity*i.PurchasePrice-i.DiscountAmount,2),CASE WHEN LEFT(ISNULL(s.GSTIN,@state),2)=@state THEN ROUND(i.GSTAmount/2,2)ELSE 0 END,CASE WHEN LEFT(ISNULL(s.GSTIN,@state),2)=@state THEN i.GSTAmount-ROUND(i.GSTAmount/2,2)ELSE 0 END,CASE WHEN LEFT(ISNULL(s.GSTIN,@state),2)<>@state THEN i.GSTAmount ELSE 0 END,0,h.RoundOff,CONVERT(bit,CASE WHEN s.GSTIN IS NOT NULL THEN 1 ELSE 0 END),LEFT(ISNULL(s.GSTIN,@state),2)FROM purchase.PurchaseInvoices h JOIN purchase.PurchaseInvoiceItems i ON i.PurchaseInvoiceId=h.PurchaseInvoiceId JOIN master.Products p ON p.ProductId=i.ProductId JOIN purchase.Suppliers s ON s.SupplierId=h.SupplierId WHERE h.IsDeleted=0 AND h.Status NOT IN('DRAFT','CANCELLED'))s ON t.SourceType=s.SourceType AND t.SourceLineId=s.SourceLineId WHEN MATCHED THEN UPDATE SET DocumentNumber=s.DocumentNumber,DocumentDate=s.DocumentDate,PartyId=s.PartyId,PartyName=s.PartyName,PartyGSTIN=s.PartyGSTIN,WarehouseId=s.WarehouseId,ProductId=s.ProductId,HSNCode=s.HSNCode,SACCode=s.SACCode,GSTRate=s.GSTRate,Quantity=s.Quantity,TaxableAmount=s.TaxableAmount,CGSTAmount=s.CGSTAmount,SGSTAmount=s.SGSTAmount,IGSTAmount=s.IGSTAmount,CessAmount=s.CessAmount,RoundOff=s.RoundOff,IsB2B=s.IsB2B,PlaceOfSupply=s.PlaceOfSupply WHEN NOT MATCHED THEN INSERT(SourceType,SourceId,SourceLineId,DocumentNumber,DocumentDate,PartyId,PartyName,PartyGSTIN,WarehouseId,ProductId,HSNCode,SACCode,GSTRate,Quantity,TaxableAmount,CGSTAmount,SGSTAmount,IGSTAmount,CessAmount,RoundOff,IsB2B,PlaceOfSupply)VALUES(s.SourceType,s.SourceId,s.SourceLineId,s.DocumentNumber,s.DocumentDate,s.PartyId,s.PartyName,s.PartyGSTIN,s.WarehouseId,s.ProductId,s.HSNCode,s.SACCode,s.GSTRate,s.Quantity,s.TaxableAmount,s.CGSTAmount,s.SGSTAmount,s.IGSTAmount,s.CessAmount,s.RoundOff,s.IsB2B,s.PlaceOfSupply);END
GO
PRINT N'Creating Procedure [gst].[GSTR3B_Get]...';


