CREATE   PROCEDURE gst.GSTR3B_Get @From datetimeoffset,@To datetimeoffset,@WarehouseId uniqueidentifier=NULL AS BEGIN SET NOCOUNT ON;EXEC gst.SyncTransactions;SELECT SUM(CASE WHEN SourceType='SALE'THEN TaxableAmount ELSE 0 END)OutwardTaxable,SUM(CASE WHEN SourceType='SALE'THEN CGSTAmount ELSE 0 END)OutputCGST,SUM(CASE WHEN SourceType='SALE'THEN SGSTAmount ELSE 0 END)OutputSGST,SUM(CASE WHEN SourceType='SALE'THEN IGSTAmount ELSE 0 END)OutputIGST,SUM(CASE WHEN SourceType='PURCHASE'THEN CGSTAmount ELSE 0 END)ITCCGST,SUM(CASE WHEN SourceType='PURCHASE'THEN SGSTAmount ELSE 0 END)ITCSGST,SUM(CASE WHEN SourceType='PURCHASE'THEN IGSTAmount ELSE 0 END)ITCIGST,SUM(CASE WHEN SourceType='SALE'THEN CGSTAmount+SGSTAmount+IGSTAmount+CessAmount ELSE 0 END)-SUM(CASE WHEN SourceType='PURCHASE'THEN CGSTAmount+SGSTAmount+IGSTAmount+CessAmount ELSE 0 END)NetTaxPayable FROM gst.GSTTransactions WHERE DocumentDate>=@From AND DocumentDate<@To AND(@WarehouseId IS NULL OR WarehouseId=@WarehouseId);END
GO
