CREATE   PROCEDURE gst.HSNSummary_Get @From datetimeoffset,@To datetimeoffset,@WarehouseId uniqueidentifier=NULL,@GSTRate decimal(5,2)=NULL AS BEGIN SET NOCOUNT ON;EXEC gst.SyncTransactions;SELECT SourceType,COALESCE(NULLIF(HSNCode,''),NULLIF(SACCode,''),'UNCLASSIFIED')HSNCode,GSTRate,SUM(Quantity)Quantity,SUM(TaxableAmount)TaxableAmount,SUM(CGSTAmount)CGSTAmount,SUM(SGSTAmount)SGSTAmount,SUM(IGSTAmount)IGSTAmount,SUM(CessAmount)CessAmount FROM gst.GSTTransactions WHERE DocumentDate>=@From AND DocumentDate<@To AND(@WarehouseId IS NULL OR WarehouseId=@WarehouseId)AND(@GSTRate IS NULL OR GSTRate=@GSTRate)GROUP BY SourceType,COALESCE(NULLIF(HSNCode,''),NULLIF(SACCode,''),'UNCLASSIFIED'),GSTRate ORDER BY HSNCode,GSTRate;END
GO
