CREATE   PROCEDURE gst.Register_Get @SourceType nvarchar(10),@From datetimeoffset,@To datetimeoffset,@WarehouseId uniqueidentifier=NULL,@PartyId uniqueidentifier=NULL,@GSTRate decimal(5,2)=NULL AS BEGIN SET NOCOUNT ON;EXEC gst.SyncTransactions;SELECT GSTTransactionId,DocumentNumber,DocumentDate,PartyId,PartyName,PartyGSTIN,WarehouseId,ProductId,HSNCode,SACCode,GSTRate,Quantity,TaxableAmount,CGSTAmount,SGSTAmount,IGSTAmount,CessAmount,ReverseChargeAmount,TaxAdjustment,RoundOff,IsB2B,PlaceOfSupply FROM gst.GSTTransactions WHERE SourceType=@SourceType AND DocumentDate>=@From AND DocumentDate<@To AND(@WarehouseId IS NULL OR WarehouseId=@WarehouseId)AND(@PartyId IS NULL OR PartyId=@PartyId)AND(@GSTRate IS NULL OR GSTRate=@GSTRate)ORDER BY DocumentDate,DocumentNumber;END
GO
