CREATE   PROCEDURE gst.TaxSummary_Get @From datetimeoffset,@To datetimeoffset,@WarehouseId uniqueidentifier=NULL,@GSTRate decimal(5,2)=NULL AS BEGIN SET NOCOUNT ON;EXEC gst.SyncTransactions;SELECT SourceType,GSTRate,SUM(TaxableAmount)TaxableAmount,SUM(CGSTAmount)CGSTAmount,SUM(SGSTAmount)SGSTAmount,SUM(IGSTAmount)IGSTAmount,SUM(CessAmount)CessAmount,SUM(CGSTAmount+SGSTAmount+IGSTAmount+CessAmount)TotalTax FROM gst.GSTTransactions WHERE DocumentDate>=@From AND DocumentDate<@To AND(@WarehouseId IS NULL OR WarehouseId=@WarehouseId)AND(@GSTRate IS NULL OR GSTRate=@GSTRate)GROUP BY SourceType,GSTRate ORDER BY SourceType,GSTRate;END
GO
