CREATE   PROCEDURE finance.CollectionFollowUp_Save @CustomerId uniqueidentifier,@InvoiceId uniqueidentifier=NULL,@FollowUpDate datetimeoffset,@NextFollowUpDate datetimeoffset=NULL,@PaymentCommitmentDate datetimeoffset=NULL,@CommunicationMode nvarchar(30),@Notes nvarchar(2000)=NULL,@Outcome nvarchar(100)=NULL,@CreatedBy nvarchar(256)=NULL AS BEGIN INSERT finance.CollectionFollowUp(CustomerId,InvoiceId,FollowUpDate,NextFollowUpDate,PaymentCommitmentDate,CommunicationMode,Notes,Outcome,CreatedBy)VALUES(@CustomerId,@InvoiceId,@FollowUpDate,@NextFollowUpDate,@PaymentCommitmentDate,@CommunicationMode,@Notes,@Outcome,@CreatedBy);SELECT SCOPE_IDENTITY();END
