GO
CREATE   PROCEDURE finance.Outstanding_List @PartyType nvarchar(10),@PartyId uniqueidentifier=NULL,@Search nvarchar(100)=NULL,@AgeBucket nvarchar(20)=NULL,@OnlyOpen bit=1 AS BEGIN SET NOCOUNT ON;EXEC finance.RefreshOutstanding;IF @PartyType='CUSTOMER'SELECT o.CustomerOutstandingId Id,o.CustomerId PartyId,c.CustomerCode PartyCode,c.CustomerName PartyName,o.InvoiceId,o.InvoiceNumber,o.InvoiceDate,o.DueDate,o.InvoiceAmount,o.ReceivedAmount PaidAmount,o.OutstandingAmount,o.AgeDays,o.AgeBucket FROM finance.CustomerOutstanding o JOIN sales.Customers c ON c.CustomerId=o.CustomerId WHERE(@PartyId IS NULL OR o.CustomerId=@PartyId)AND(@OnlyOpen=0 OR o.OutstandingAmount>0)AND(@AgeBucket IS NULL OR o.AgeBucket=@AgeBucket)AND(@Search IS NULL OR c.CustomerName LIKE'%'+@Search+'%'OR o.InvoiceNumber LIKE'%'+@Search+'%')ORDER BY o.DueDate;ELSE SELECT o.SupplierOutstandingId,o.SupplierId,s.SupplierCode,s.SupplierName,o.PurchaseInvoiceId,o.InvoiceNumber,o.InvoiceDate,o.DueDate,o.InvoiceAmount,o.PaidAmount,o.OutstandingAmount,o.AgeDays,o.AgeBucket FROM finance.SupplierOutstanding o JOIN purchase.Suppliers s ON s.SupplierId=o.SupplierId WHERE(@PartyId IS NULL OR o.SupplierId=@PartyId)AND(@OnlyOpen=0 OR o.OutstandingAmount>0)AND(@AgeBucket IS NULL OR o.AgeBucket=@AgeBucket)AND(@Search IS NULL OR s.SupplierName LIKE'%'+@Search+'%'OR o.InvoiceNumber LIKE'%'+@Search+'%')ORDER BY o.DueDate;END
GO
PRINT N'Creating Procedure [finance].[PostPartyTransaction]...';


GO
CREATE PROCEDURE finance.PostPartyTransaction @TransactionType NVARCHAR(10),@PartyType NVARCHAR(10),@PartyId UNIQUEIDENTIFIER,@PaymentMode NVARCHAR(30),@Amount DECIMAL(18,2),@EntryDate DATETIMEOFFSET,@ReferenceNumber NVARCHAR(100)=NULL,@Narration NVARCHAR(500)=NULL,@CreatedBy NVARCHAR(256)=NULL,@SourceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @TransactionType NOT IN('RECEIPT','PAYMENT')OR @PartyType NOT IN('CUSTOMER','SUPPLIER')OR @Amount<=0 THROW 51300,'Invalid financial transaction.',1;DECLARE @ModeId UNIQUEIDENTIFIER,@Book NVARCHAR(10);SELECT @ModeId=PaymentModeId,@Book=BookType FROM finance.PaymentModes WHERE ModeCode=@PaymentMode AND IsActive=1;IF @ModeId IS NULL OR @Book='CREDIT'THROW 51300,'Cash or bank payment mode is required.',1;BEGIN TRAN;DECLARE @Source UNIQUEIDENTIFIER=ISNULL(@SourceId,NEWID());DECLARE @J UNIQUEIDENTIFIER=NEWID(),@No NVARCHAR(50)=CONCAT('JV-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20))),@Cash UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='CASH'),@Bank UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='BANK'),@Party UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode=CASE WHEN @PartyType='CUSTOMER'THEN'CUSTOMER'ELSE'SUPPLIER'END),@BookAccount UNIQUEIDENTIFIER;SET @BookAccount=CASE WHEN @Book='CASH'THEN @Cash ELSE @Bank END;INSERT finance.JournalEntries(JournalEntryId,JournalNumber,EntryDate,TransactionType,ReferenceType,ReferenceId,Narration,CreatedBy)VALUES(@J,@No,@EntryDate,@TransactionType,@PartyType,@Source,@Narration,@CreatedBy);IF @TransactionType='RECEIPT'INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,@BookAccount,@Amount,0),(@J,@Party,0,@Amount);ELSE INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,@Party,@Amount,0),(@J,@BookAccount,0,@Amount);INSERT finance.LedgerEntries(JournalEntryId,AccountId,EntryDate,ReferenceType,ReferenceId,DebitAmount,CreditAmount,Narration)SELECT @J,AccountId,@EntryDate,@PartyType,@Source,DebitAmount,CreditAmount,@Narration FROM finance.JournalEntryDetails WHERE JournalEntryId=@J;INSERT finance.DayBook(JournalEntryId,EntryDate,TransactionType,ReferenceType,ReferenceId,ReferenceNumber,DebitTotal,CreditTotal,Narration)VALUES(@J,@EntryDate,@TransactionType,@PartyType,@Source,@ReferenceNumber,@Amount,@Amount,@Narration);IF @PartyType='CUSTOMER'INSERT finance.CustomerLedger(CustomerId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@PartyId,@J,@EntryDate,@TransactionType,@Source,@ReferenceNumber,CASE WHEN @TransactionType='PAYMENT'THEN @Amount ELSE 0 END,CASE WHEN @TransactionType='RECEIPT'THEN @Amount ELSE 0 END,@Narration);ELSE INSERT finance.SupplierLedger(SupplierId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@PartyId,@J,@EntryDate,@TransactionType,@Source,@ReferenceNumber,CASE WHEN @TransactionType='RECEIPT'THEN @Amount ELSE 0 END,CASE WHEN @TransactionType='PAYMENT'THEN @Amount ELSE 0 END,@Narration);IF @Book='CASH'INSERT finance.CashBook(JournalEntryId,EntryDate,EntryType,ReferenceId,AmountIn,AmountOut,Narration)VALUES(@J,@EntryDate,CASE WHEN @TransactionType='RECEIPT'THEN'CASH IN'ELSE'CASH OUT'END,@Source,CASE WHEN @TransactionType='RECEIPT'THEN @Amount ELSE 0 END,CASE WHEN @TransactionType='PAYMENT'THEN @Amount ELSE 0 END,@Narration);ELSE INSERT finance.BankBook(JournalEntryId,PaymentModeId,EntryDate,EntryType,ReferenceId,ReferenceNumber,AmountIn,AmountOut,Narration)VALUES(@J,@ModeId,@EntryDate,@TransactionType,@Source,@ReferenceNumber,CASE WHEN @TransactionType='RECEIPT'THEN @Amount ELSE 0 END,CASE WHEN @TransactionType='PAYMENT'THEN @Amount ELSE 0 END,@Narration);COMMIT;SELECT @J JournalEntryId,@No JournalNumber;END
GO
PRINT N'Creating Procedure [finance].[PostPayment]...';


GO
CREATE   PROCEDURE finance.PostPayment @Domain NVARCHAR(10),@PaymentId UNIQUEIDENTIFIER,@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @Type NVARCHAR(30)=CONCAT(@Domain,'_PAYMENT');IF EXISTS(SELECT 1 FROM finance.JournalEntries WHERE ReferenceType=@Type AND ReferenceId=@PaymentId)RETURN;DECLARE @J UNIQUEIDENTIFIER=NEWID(),@No NVARCHAR(50)=CONCAT('JV-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20))),@Date DATETIMEOFFSET,@PartyId UNIQUEIDENTIFIER,@Amount DECIMAL(18,2),@Mode NVARCHAR(30),@Reference NVARCHAR(100),@ModeId UNIQUEIDENTIFIER,@Book NVARCHAR(10),@PartyAccount UNIQUEIDENTIFIER,@Cash UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='CASH'),@Bank UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='BANK');IF @Domain='PURCHASE'SELECT @Date=p.PaymentDate,@PartyId=i.SupplierId,@Amount=p.Amount,@Mode=m.MethodCode,@Reference=p.ReferenceNumber FROM purchase.PurchasePayments p JOIN purchase.PurchaseInvoices i ON i.PurchaseInvoiceId=p.PurchaseInvoiceId JOIN sales.PaymentMethods m ON m.PaymentMethodId=p.PaymentMethodId WHERE p.PurchasePaymentId=@PaymentId;ELSE SELECT @Date=p.PaymentDate,@PartyId=i.CustomerId,@Amount=p.Amount,@Mode=m.MethodCode,@Reference=p.ReferenceNumber FROM sales.SalesPayments p JOIN sales.SalesInvoices i ON i.InvoiceId=p.InvoiceId JOIN sales.PaymentMethods m ON m.PaymentMethodId=p.PaymentMethodId WHERE p.PaymentId=@PaymentId;SELECT @ModeId=PaymentModeId,@Book=BookType FROM finance.PaymentModes WHERE ModeCode=@Mode;IF @Amount IS NULL OR @Book='CREDIT'RETURN;SET @PartyAccount=(SELECT AccountId FROM finance.Accounts WHERE AccountCode=CASE WHEN @Domain='PURCHASE'THEN'SUPPLIER'ELSE'CUSTOMER'END);INSERT finance.JournalEntries(JournalEntryId,JournalNumber,EntryDate,TransactionType,ReferenceType,ReferenceId,Narration,CreatedBy)VALUES(@J,@No,@Date,@Type,@Type,@PaymentId,CONCAT(@Domain,' payment'),@CreatedBy);IF @Domain='PURCHASE'INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,@PartyAccount,@Amount,0),(@J,CASE WHEN @Book='CASH'THEN @Cash ELSE @Bank END,0,@Amount);ELSE INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,CASE WHEN @Book='CASH'THEN @Cash ELSE @Bank END,@Amount,0),(@J,@PartyAccount,0,@Amount);INSERT finance.LedgerEntries(JournalEntryId,AccountId,EntryDate,ReferenceType,ReferenceId,DebitAmount,CreditAmount,Narration)SELECT @J,AccountId,@Date,@Type,@PaymentId,DebitAmount,CreditAmount,CONCAT(@Domain,' payment')FROM finance.JournalEntryDetails WHERE JournalEntryId=@J;INSERT finance.DayBook(JournalEntryId,EntryDate,TransactionType,ReferenceType,ReferenceId,ReferenceNumber,DebitTotal,CreditTotal,Narration)VALUES(@J,@Date,@Type,@Type,@PaymentId,@Reference,@Amount,@Amount,CONCAT(@Domain,' payment'));IF @Domain='PURCHASE'INSERT finance.SupplierLedger(SupplierId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount)VALUES(@PartyId,@J,@Date,'PAYMENT',@PaymentId,@Reference,0,@Amount);ELSE IF @PartyId IS NOT NULL INSERT finance.CustomerLedger(CustomerId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount)VALUES(@PartyId,@J,@Date,'RECEIPT',@PaymentId,@Reference,0,@Amount);IF @Book='CASH'INSERT finance.CashBook(JournalEntryId,EntryDate,EntryType,ReferenceId,AmountIn,AmountOut,Narration)VALUES(@J,@Date,CASE WHEN @Domain='SALE'THEN'CASH IN'ELSE'CASH OUT'END,@PaymentId,CASE WHEN @Domain='SALE'THEN @Amount ELSE 0 END,CASE WHEN @Domain='PURCHASE'THEN @Amount ELSE 0 END,CONCAT(@Domain,' payment'));ELSE INSERT finance.BankBook(JournalEntryId,PaymentModeId,EntryDate,EntryType,ReferenceId,ReferenceNumber,AmountIn,AmountOut,Narration)VALUES(@J,@ModeId,@Date,CASE WHEN @Domain='SALE'THEN'RECEIPT'ELSE'PAYMENT'END,@PaymentId,@Reference,CASE WHEN @Domain='SALE'THEN @Amount ELSE 0 END,CASE WHEN @Domain='PURCHASE'THEN @Amount ELSE 0 END,CONCAT(@Domain,' payment'));END
GO
