GO
CREATE   PROCEDURE finance.PostSource @SourceType NVARCHAR(30),@SourceId UNIQUEIDENTIFIER,@CreatedBy NVARCHAR(256)=NULL AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF EXISTS(SELECT 1 FROM finance.JournalEntries WHERE ReferenceType=@SourceType AND ReferenceId=@SourceId AND TransactionType=@SourceType)RETURN;
DECLARE @J UNIQUEIDENTIFIER=NEWID(),@No NVARCHAR(50)=CONCAT('JV-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20))),@Date DATETIMEOFFSET,@RefNo NVARCHAR(50),@Narr NVARCHAR(500),@Customer UNIQUEIDENTIFIER,@Supplier UNIQUEIDENTIFIER,@Grand DECIMAL(18,2),@Tax DECIMAL(18,2),@Net DECIMAL(18,2),@Paid DECIMAL(18,2)=0;
DECLARE @Cash UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='CASH'),@Bank UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='BANK'),@Cust UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='CUSTOMER'),@Supp UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='SUPPLIER'),@Inv UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='INVENTORY'),@InGST UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='INPUT_GST'),@OutGST UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='OUTPUT_GST'),@Sales UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='SALES'),@PRet UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='PURCHASE_RETURN'),@SRet UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='SALES_RETURN');
IF @SourceType='PURCHASE'BEGIN SELECT @Date=InvoiceDate,@RefNo=InvoiceNumber,@Supplier=SupplierId,@Grand=GrandTotal,@Tax=TaxAmount,@Net=GrandTotal-TaxAmount,@Narr=Remarks FROM purchase.PurchaseInvoices WHERE PurchaseInvoiceId=@SourceId AND Status<>'DRAFT';IF @Grand IS NULL RETURN;SELECT @Paid=ISNULL(SUM(p.Amount),0)FROM purchase.PurchasePayments p WHERE p.PurchaseInvoiceId=@SourceId AND p.Status='COMPLETED';INSERT finance.JournalEntries(JournalEntryId,JournalNumber,EntryDate,TransactionType,ReferenceType,ReferenceId,Narration,CreatedBy)VALUES(@J,@No,@Date,@SourceType,@SourceType,@SourceId,@Narr,@CreatedBy);INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount,Description)VALUES(@J,@Inv,@Net,0,'Inventory and landed cost'),(@J,@InGST,@Tax,0,'Input GST'),(@J,@Supp,0,@Grand,'Supplier payable');IF @Paid>0 INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount,Description)VALUES(@J,@Supp,@Paid,0,'Supplier payments');INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount,Description)SELECT @J,CASE WHEN fm.BookType='CASH'THEN @Cash ELSE @Bank END,0,SUM(p.Amount),pm.MethodCode FROM purchase.PurchasePayments p JOIN sales.PaymentMethods pm ON pm.PaymentMethodId=p.PaymentMethodId JOIN finance.PaymentModes fm ON fm.ModeCode=pm.MethodCode WHERE p.PurchaseInvoiceId=@SourceId AND p.Status='COMPLETED'AND fm.BookType<>'CREDIT'GROUP BY fm.BookType,pm.MethodCode;INSERT finance.SupplierLedger(SupplierId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@Supplier,@J,@Date,'PURCHASE',@SourceId,@RefNo,@Grand,0,@Narr);IF @Paid>0 INSERT finance.SupplierLedger(SupplierId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@Supplier,@J,@Date,'PAYMENT',@SourceId,@RefNo,0,@Paid,'Purchase payment');INSERT finance.CashBook(JournalEntryId,EntryDate,EntryType,ReferenceId,AmountOut,Narration)SELECT @J,p.PaymentDate,'CASH OUT',@SourceId,p.Amount,'Purchase payment'FROM purchase.PurchasePayments p JOIN sales.PaymentMethods pm ON pm.PaymentMethodId=p.PaymentMethodId WHERE p.PurchaseInvoiceId=@SourceId AND pm.MethodCode='CASH';INSERT finance.BankBook(JournalEntryId,PaymentModeId,EntryDate,EntryType,ReferenceId,ReferenceNumber,AmountOut,Narration)SELECT @J,fm.PaymentModeId,p.PaymentDate,'PAYMENT',@SourceId,p.ReferenceNumber,p.Amount,'Purchase payment'FROM purchase.PurchasePayments p JOIN sales.PaymentMethods pm ON pm.PaymentMethodId=p.PaymentMethodId JOIN finance.PaymentModes fm ON fm.ModeCode=pm.MethodCode WHERE p.PurchaseInvoiceId=@SourceId AND fm.BookType='BANK';END
ELSE IF @SourceType='SALE'BEGIN SELECT @Date=InvoiceDate,@RefNo=InvoiceNumber,@Customer=CustomerId,@Grand=GrandTotal,@Tax=TaxAmount,@Net=GrandTotal-TaxAmount,@Narr=Remarks FROM sales.SalesInvoices WHERE InvoiceId=@SourceId AND Status NOT IN('HELD','SUSPENDED','CANCELLED','VOID');IF @Grand IS NULL RETURN;SELECT @Paid=ISNULL(SUM(p.Amount),0)FROM sales.SalesPayments p WHERE p.InvoiceId=@SourceId AND p.Status='COMPLETED';INSERT finance.JournalEntries(JournalEntryId,JournalNumber,EntryDate,TransactionType,ReferenceType,ReferenceId,Narration,CreatedBy)VALUES(@J,@No,@Date,@SourceType,@SourceType,@SourceId,@Narr,@CreatedBy);INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount,Description)VALUES(@J,@Cust,@Grand,0,'Customer receivable'),(@J,@Sales,0,@Net,'Sales'),(@J,@OutGST,0,@Tax,'Output GST');INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount,Description)SELECT @J,CASE WHEN fm.BookType='CASH'THEN @Cash ELSE @Bank END,SUM(p.Amount),0,pm.MethodCode FROM sales.SalesPayments p JOIN sales.PaymentMethods pm ON pm.PaymentMethodId=p.PaymentMethodId JOIN finance.PaymentModes fm ON fm.ModeCode=pm.MethodCode WHERE p.InvoiceId=@SourceId AND p.Status='COMPLETED'AND fm.BookType<>'CREDIT'GROUP BY fm.BookType,pm.MethodCode;IF @Paid>0 INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount,Description)VALUES(@J,@Cust,0,@Paid,'Customer receipts');IF @Customer IS NOT NULL BEGIN INSERT finance.CustomerLedger(CustomerId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@Customer,@J,@Date,'SALE',@SourceId,@RefNo,@Grand,0,@Narr);IF @Paid>0 INSERT finance.CustomerLedger(CustomerId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@Customer,@J,@Date,'RECEIPT',@SourceId,@RefNo,0,@Paid,'Sales receipt');END;INSERT finance.CashBook(JournalEntryId,EntryDate,EntryType,ReferenceId,AmountIn,Narration)SELECT @J,p.PaymentDate,'CASH IN',@SourceId,p.Amount,'Sales receipt'FROM sales.SalesPayments p JOIN sales.PaymentMethods pm ON pm.PaymentMethodId=p.PaymentMethodId WHERE p.InvoiceId=@SourceId AND pm.MethodCode='CASH';INSERT finance.BankBook(JournalEntryId,PaymentModeId,EntryDate,EntryType,ReferenceId,ReferenceNumber,AmountIn,Narration)SELECT @J,fm.PaymentModeId,p.PaymentDate,'RECEIPT',@SourceId,p.ReferenceNumber,p.Amount,'Sales receipt'FROM sales.SalesPayments p JOIN sales.PaymentMethods pm ON pm.PaymentMethodId=p.PaymentMethodId JOIN finance.PaymentModes fm ON fm.ModeCode=pm.MethodCode WHERE p.InvoiceId=@SourceId AND fm.BookType='BANK';END
ELSE IF @SourceType='PURCHASE_RETURN'BEGIN SELECT @Date=MAX(r.ReturnDate),@Supplier=MAX(i.SupplierId),@RefNo=MAX(r.ReturnNumber),@Grand=SUM(r.AdjustmentAmount),@Narr=MAX(r.Reason)FROM purchase.PurchaseReturns r JOIN purchase.PurchaseInvoices i ON i.PurchaseInvoiceId=r.PurchaseInvoiceId WHERE r.PurchaseInvoiceId=@SourceId;IF @Grand IS NULL RETURN;INSERT finance.JournalEntries(JournalEntryId,JournalNumber,EntryDate,TransactionType,ReferenceType,ReferenceId,Narration,CreatedBy)VALUES(@J,@No,@Date,@SourceType,@SourceType,@SourceId,@Narr,@CreatedBy);INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,@Supp,@Grand,0),(@J,@PRet,0,@Grand);INSERT finance.SupplierLedger(SupplierId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@Supplier,@J,@Date,'PURCHASE_RETURN',@SourceId,@RefNo,0,@Grand,@Narr);END
ELSE IF @SourceType='SALE_RETURN'BEGIN SELECT @Date=MAX(r.ReturnDate),@Customer=MAX(i.CustomerId),@RefNo=MAX(r.ReturnNumber),@Grand=SUM(r.RefundAmount),@Narr=MAX(r.Reason)FROM sales.SalesInvoiceReturns r JOIN sales.SalesInvoices i ON i.InvoiceId=r.InvoiceId WHERE r.InvoiceId=@SourceId;IF @Grand IS NULL RETURN;INSERT finance.JournalEntries(JournalEntryId,JournalNumber,EntryDate,TransactionType,ReferenceType,ReferenceId,Narration,CreatedBy)VALUES(@J,@No,@Date,@SourceType,@SourceType,@SourceId,@Narr,@CreatedBy);INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,@SRet,@Grand,0),(@J,@Cust,0,@Grand);IF @Customer IS NOT NULL INSERT finance.CustomerLedger(CustomerId,JournalEntryId,EntryDate,EntryType,ReferenceId,ReferenceNumber,DebitAmount,CreditAmount,Narration)VALUES(@Customer,@J,@Date,'CREDIT_NOTE',@SourceId,@RefNo,0,@Grand,@Narr);END
IF EXISTS(SELECT 1 FROM finance.JournalEntries WHERE JournalEntryId=@J)BEGIN DECLARE @Dr DECIMAL(18,2)=(SELECT SUM(DebitAmount)FROM finance.JournalEntryDetails WHERE JournalEntryId=@J),@Cr DECIMAL(18,2)=(SELECT SUM(CreditAmount)FROM finance.JournalEntryDetails WHERE JournalEntryId=@J);IF ABS(@Dr-@Cr)>.01 THROW 51300,'Financial journal is not balanced.',1;INSERT finance.LedgerEntries(JournalEntryId,AccountId,EntryDate,ReferenceType,ReferenceId,DebitAmount,CreditAmount,Narration)SELECT @J,AccountId,@Date,@SourceType,@SourceId,DebitAmount,CreditAmount,Description FROM finance.JournalEntryDetails WHERE JournalEntryId=@J;INSERT finance.DayBook(JournalEntryId,EntryDate,TransactionType,ReferenceType,ReferenceId,ReferenceNumber,DebitTotal,CreditTotal,Narration)VALUES(@J,@Date,@SourceType,@SourceType,@SourceId,@RefNo,@Dr,@Cr,@Narr);END;END
GO
PRINT N'Creating Procedure [finance].[PostStockAdjustment]...';


GO
CREATE   PROCEDURE finance.PostStockAdjustment @TransactionId UNIQUEIDENTIFIER,@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF EXISTS(SELECT 1 FROM finance.JournalEntries WHERE ReferenceType='STOCK_ADJUSTMENT'AND ReferenceId=@TransactionId)RETURN;DECLARE @J UNIQUEIDENTIFIER=NEWID(),@No NVARCHAR(50)=CONCAT('JV-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20))),@Date DATETIMEOFFSET,@Type NVARCHAR(10),@Ref NVARCHAR(50),@Amount DECIMAL(18,2),@Narr NVARCHAR(500),@Inv UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='INVENTORY'),@Adj UNIQUEIDENTIFIER=(SELECT AccountId FROM finance.Accounts WHERE AccountCode='STOCK_ADJUST');SELECT @Date=t.TransactionDate,@Type=a.AdjustmentType,@Ref=a.AdjustmentNo,@Narr=t.Remarks,@Amount=SUM(d.Quantity*d.UnitCost)FROM inventory.StockAdjustments a JOIN inventory.InventoryTransactions t ON t.TransactionId=a.TransactionId JOIN inventory.InventoryTransactionDetails d ON d.TransactionId=t.TransactionId WHERE a.TransactionId=@TransactionId GROUP BY t.TransactionDate,a.AdjustmentType,a.AdjustmentNo,t.Remarks;IF @Amount IS NULL RETURN;INSERT finance.JournalEntries(JournalEntryId,JournalNumber,EntryDate,TransactionType,ReferenceType,ReferenceId,Narration,CreatedBy)VALUES(@J,@No,@Date,'STOCK_ADJUSTMENT','STOCK_ADJUSTMENT',@TransactionId,@Narr,@CreatedBy);IF @Type='INCREASE'INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,@Inv,@Amount,0),(@J,@Adj,0,@Amount);ELSE INSERT finance.JournalEntryDetails(JournalEntryId,AccountId,DebitAmount,CreditAmount)VALUES(@J,@Adj,@Amount,0),(@J,@Inv,0,@Amount);INSERT finance.LedgerEntries(JournalEntryId,AccountId,EntryDate,ReferenceType,ReferenceId,DebitAmount,CreditAmount,Narration)SELECT @J,AccountId,@Date,'STOCK_ADJUSTMENT',@TransactionId,DebitAmount,CreditAmount,@Narr FROM finance.JournalEntryDetails WHERE JournalEntryId=@J;INSERT finance.DayBook(JournalEntryId,EntryDate,TransactionType,ReferenceType,ReferenceId,ReferenceNumber,DebitTotal,CreditTotal,Narration)VALUES(@J,@Date,'STOCK_ADJUSTMENT','STOCK_ADJUSTMENT',@TransactionId,@Ref,@Amount,@Amount,@Narr);END
GO
PRINT N'Creating Procedure [finance].[Receipt_Post]...';


GO
CREATE   PROCEDURE finance.Receipt_Post @CustomerId uniqueidentifier,@ReceiptType nvarchar(30),@ReceiptDate datetimeoffset,@ReferenceNumber nvarchar(100)=NULL,@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@AllocationsJson nvarchar(max)=NULL,@CreatedBy nvarchar(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY DECLARE @id uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('RCT-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff')),@total decimal(18,2),@allocated decimal(18,2);DECLARE @items table(PaymentMode nvarchar(30),Amount decimal(18,2),ReferenceNumber nvarchar(100),ChequeNumber nvarchar(50),ChequeDate date,BankName nvarchar(150));INSERT @items SELECT * FROM OPENJSON(@ItemsJson)WITH(PaymentMode nvarchar(30)'$.PaymentMode',Amount decimal(18,2)'$.Amount',ReferenceNumber nvarchar(100)'$.ReferenceNumber',ChequeNumber nvarchar(50)'$.ChequeNumber',ChequeDate date'$.ChequeDate',BankName nvarchar(150)'$.BankName');DECLARE @alloc table(InvoiceId uniqueidentifier,Amount decimal(18,2));INSERT @alloc SELECT * FROM OPENJSON(ISNULL(@AllocationsJson,'[]'))WITH(InvoiceId uniqueidentifier'$.InvoiceId',Amount decimal(18,2)'$.Amount');SELECT @total=SUM(Amount)FROM @items;SELECT @allocated=ISNULL(SUM(Amount),0)FROM @alloc;IF ISNULL(@total,0)<=0 OR @allocated>@total THROW 51320,'Receipt totals or allocations are invalid.',1;IF EXISTS(SELECT 1 FROM @alloc a LEFT JOIN sales.SalesInvoices i ON i.InvoiceId=a.InvoiceId AND i.CustomerId=@CustomerId WHERE i.InvoiceId IS NULL OR a.Amount<=0 OR a.Amount>i.BalanceAmount)THROW 51321,'Receipt allocation exceeds invoice outstanding or invoice is invalid.',1;INSERT finance.Receipts(ReceiptId,ReceiptNumber,ReceiptDate,CustomerId,ReceiptType,TotalAmount,AllocatedAmount,ReferenceNumber,Remarks,CreatedBy)VALUES(@id,@no,@ReceiptDate,@CustomerId,@ReceiptType,@total,@allocated,@ReferenceNumber,@Remarks,@CreatedBy);INSERT finance.ReceiptItems(ReceiptId,PaymentModeId,Amount,ReferenceNumber,ChequeNumber,ChequeDate,BankName)SELECT @id,m.PaymentModeId,i.Amount,i.ReferenceNumber,i.ChequeNumber,i.ChequeDate,i.BankName FROM @items i JOIN finance.PaymentModes m ON m.ModeCode=i.PaymentMode AND m.IsActive=1;IF @@ROWCOUNT<>(SELECT COUNT(*)FROM @items)THROW 51322,'One or more payment modes are invalid.',1;INSERT finance.ReceiptAllocation(ReceiptId,InvoiceId,AllocatedAmount,CreatedBy)SELECT @id,InvoiceId,Amount,@CreatedBy FROM @alloc;UPDATE i SET PaidAmount=i.PaidAmount+a.Amount,ModifiedOn=SYSUTCDATETIME()FROM sales.SalesInvoices i JOIN @alloc a ON a.InvoiceId=i.InvoiceId;DECLARE @mode nvarchar(30),@amount decimal(18,2),@itemref nvarchar(100),@journal uniqueidentifier,@jn nvarchar(50);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT PaymentMode,Amount,COALESCE(ReferenceNumber,@ReferenceNumber)FROM @items;OPEN c;FETCH NEXT FROM c INTO @mode,@amount,@itemref;WHILE @@FETCH_STATUS=0 BEGIN DECLARE @r table(Id uniqueidentifier,Number nvarchar(50));INSERT @r EXEC finance.PostPartyTransaction 'RECEIPT','CUSTOMER',@CustomerId,@mode,@amount,@ReceiptDate,@itemref,@Remarks,@CreatedBy;SELECT TOP 1 @journal=Id,@jn=Number FROM @r;UPDATE TOP(1)finance.ReceiptItems SET JournalEntryId=@journal WHERE ReceiptId=@id AND JournalEntryId IS NULL AND Amount=@amount;DELETE @r;FETCH NEXT FROM c INTO @mode,@amount,@itemref;END CLOSE c;DEALLOCATE c;EXEC finance.RefreshOutstanding;COMMIT;SELECT @id DocumentId,@no DocumentNumber,@total TotalAmount,@allocated AllocatedAmount;END TRY BEGIN CATCH IF CURSOR_STATUS('local','c')>=0 BEGIN CLOSE c;DEALLOCATE c;END IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
PRINT N'Creating Procedure [finance].[ReceivablePayable_List]...';


GO
CREATE   PROCEDURE finance.ReceivablePayable_List @Kind nvarchar(20),@Search nvarchar(100)=NULL,@PartyId uniqueidentifier=NULL,@From datetimeoffset=NULL,@To datetimeoffset=NULL,@PageNumber int=1,@PageSize int=20 AS BEGIN SET NOCOUNT ON;IF @Kind='RECEIPT'BEGIN SELECT r.ReceiptId Id,r.ReceiptNumber Number,r.ReceiptDate EntryDate,c.CustomerCode PartyCode,c.CustomerName PartyName,r.ReceiptType EntryType,r.TotalAmount,r.AllocatedAmount,r.OnAccountAmount,r.Status,r.ReferenceNumber,r.Remarks FROM finance.Receipts r JOIN sales.Customers c ON c.CustomerId=r.CustomerId WHERE(@PartyId IS NULL OR r.CustomerId=@PartyId)AND(@Search IS NULL OR r.ReceiptNumber LIKE'%'+@Search+'%'OR c.CustomerName LIKE'%'+@Search+'%')AND(@From IS NULL OR r.ReceiptDate>=@From)AND(@To IS NULL OR r.ReceiptDate<=@To)ORDER BY r.ReceiptDate DESC OFFSET(CASE WHEN @PageNumber<1 THEN 0 ELSE @PageNumber-1 END)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;SELECT COUNT(*)FROM finance.Receipts r JOIN sales.Customers c ON c.CustomerId=r.CustomerId WHERE(@PartyId IS NULL OR r.CustomerId=@PartyId)AND(@Search IS NULL OR r.ReceiptNumber LIKE'%'+@Search+'%'OR c.CustomerName LIKE'%'+@Search+'%')AND(@From IS NULL OR r.ReceiptDate>=@From)AND(@To IS NULL OR r.ReceiptDate<=@To);END ELSE BEGIN SELECT p.PaymentId,p.PaymentNumber,p.PaymentDate,s.SupplierCode,s.SupplierName,p.PaymentType,p.TotalAmount,p.AllocatedAmount,p.OnAccountAmount,p.Status,p.ReferenceNumber,p.Remarks FROM finance.Payments p JOIN purchase.Suppliers s ON s.SupplierId=p.SupplierId WHERE(@PartyId IS NULL OR p.SupplierId=@PartyId)AND(@Search IS NULL OR p.PaymentNumber LIKE'%'+@Search+'%'OR s.SupplierName LIKE'%'+@Search+'%')AND(@From IS NULL OR p.PaymentDate>=@From)AND(@To IS NULL OR p.PaymentDate<=@To)ORDER BY p.PaymentDate DESC OFFSET(CASE WHEN @PageNumber<1 THEN 0 ELSE @PageNumber-1 END)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;SELECT COUNT(*)FROM finance.Payments p JOIN purchase.Suppliers s ON s.SupplierId=p.SupplierId WHERE(@PartyId IS NULL OR p.SupplierId=@PartyId)AND(@Search IS NULL OR p.PaymentNumber LIKE'%'+@Search+'%'OR s.SupplierName LIKE'%'+@Search+'%')AND(@From IS NULL OR p.PaymentDate>=@From)AND(@To IS NULL OR p.PaymentDate<=@To);END END
GO
PRINT N'Creating Procedure [inventory].[PhysicalVerification_List]...';


GO
CREATE   PROCEDURE inventory.PhysicalVerification_List @Search nvarchar(100)=NULL,@WarehouseId uniqueidentifier=NULL,@From datetimeoffset=NULL,@To datetimeoffset=NULL,@PageNumber int=1,@PageSize int=20 AS BEGIN SET NOCOUNT ON;WITH q AS(SELECT h.VerificationId Id,h.VerificationNo Number,h.VerificationDate Date,'PHYSICAL_COUNT' Type,h.ApprovalStatus Status,h.Remarks,SUM(ABS(ISNULL(i.VarianceQuantity,0)))TotalQuantity,COUNT(i.VerificationItemId)ItemCount FROM inventory.PhysicalStockVerification h LEFT JOIN inventory.PhysicalStockVerificationItems i ON i.VerificationId=h.VerificationId WHERE(@Search IS NULL OR h.VerificationNo LIKE '%'+@Search+'%')AND(@WarehouseId IS NULL OR h.WarehouseId=@WarehouseId)GROUP BY h.VerificationId,h.VerificationNo,h.VerificationDate,h.ApprovalStatus,h.Remarks)SELECT * FROM q ORDER BY Date DESC OFFSET (CASE WHEN @PageNumber<1 THEN 0 ELSE @PageNumber-1 END)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;SELECT COUNT(*) FROM inventory.PhysicalStockVerification h WHERE(@Search IS NULL OR h.VerificationNo LIKE '%'+@Search+'%')AND(@WarehouseId IS NULL OR h.WarehouseId=@WarehouseId);END
GO
PRINT N'Creating Procedure [inventory].[RefreshStockControl]...';


GO
CREATE PROCEDURE inventory.RefreshStockControl AS BEGIN SET NOCOUNT ON;BEGIN TRAN;UPDATE inventory.InventoryAlerts SET Status='RESOLVED',ResolvedOn=SYSUTCDATETIME() WHERE Status='ACTIVE';INSERT inventory.InventoryAlerts(ProductId,WarehouseId,AlertType,CurrentQuantity,SuggestedQuantity,Detail)SELECT p.ProductId,w.WarehouseId,CASE WHEN ISNULL(s.Qty,0)<0 THEN 'NEGATIVE_STOCK' WHEN ISNULL(s.Qty,0)=0 THEN 'OUT_OF_STOCK' WHEN ISNULL(s.Qty,0)<=p.ReorderLevel THEN 'LOW_STOCK' WHEN p.MaximumStock>0 AND ISNULL(s.Qty,0)>p.MaximumStock THEN 'OVER_STOCK' END,ISNULL(s.Qty,0),CASE WHEN p.MaximumStock>ISNULL(s.Qty,0) THEN p.MaximumStock-ISNULL(s.Qty,0) ELSE 0 END,'Generated from current inventory thresholds' FROM master.Products p CROSS JOIN inventory.Warehouses w OUTER APPLY(SELECT SUM(QuantityAvailable)Qty FROM inventory.InventoryBalances b WHERE b.ProductId=p.ProductId AND b.WarehouseId=w.WarehouseId)s WHERE p.IsActive=1 AND p.IsDeleted=0 AND w.IsActive=1 AND (ISNULL(s.Qty,0)<=p.ReorderLevel OR p.MaximumStock>0 AND ISNULL(s.Qty,0)>p.MaximumStock);INSERT inventory.InventoryAlerts(ProductId,WarehouseId,BatchNo,AlertType,CurrentQuantity,SuggestedQuantity,Detail) SELECT b.ProductId,b.WarehouseId,b.BatchNo,CASE WHEN MIN(i.ExpiryDate)<CAST(SYSUTCDATETIME() AS date) THEN 'EXPIRED_STOCK' ELSE 'EXPIRING_SOON' END,SUM(b.QuantityAvailable),0,CONCAT('Batch ',b.BatchNo,' expires ',CONVERT(nvarchar(10),MIN(i.ExpiryDate),23)) FROM inventory.InventoryBalances b JOIN purchase.PurchaseInvoiceItems i ON i.ProductId=b.ProductId AND ISNULL(i.BatchNo,'')=ISNULL(b.BatchNo,'') WHERE b.QuantityAvailable>0 AND i.ExpiryDate IS NOT NULL AND i.ExpiryDate<=DATEADD(day,30,CAST(SYSUTCDATETIME() AS date)) GROUP BY b.ProductId,b.WarehouseId,b.BatchNo;DELETE inventory.ReorderSuggestions WHERE Status='OPEN';INSERT inventory.ReorderSuggestions(ProductId,WarehouseId,CurrentStock,PendingPurchase,SalesVelocity,SuggestedQuantity)SELECT p.ProductId,w.WarehouseId,ISNULL(s.Qty,0),ISNULL(pp.Qty,0),ISNULL(v.Qty,0)/30.0,CASE WHEN p.MaximumStock>ISNULL(s.Qty,0)+ISNULL(pp.Qty,0) THEN p.MaximumStock-ISNULL(s.Qty,0)-ISNULL(pp.Qty,0) ELSE p.ReorderLevel+ISNULL(v.Qty,0)-ISNULL(s.Qty,0)-ISNULL(pp.Qty,0) END FROM master.Products p CROSS JOIN inventory.Warehouses w OUTER APPLY(SELECT SUM(QuantityAvailable)Qty FROM inventory.InventoryBalances b WHERE b.ProductId=p.ProductId AND b.WarehouseId=w.WarehouseId)s OUTER APPLY(SELECT SUM(i.Quantity+i.FreeQuantity-i.ReturnedQuantity)Qty FROM purchase.PurchaseInvoiceItems i JOIN purchase.PurchaseInvoices h ON h.PurchaseInvoiceId=i.PurchaseInvoiceId WHERE i.ProductId=p.ProductId AND h.WarehouseId=w.WarehouseId AND h.Status IN('DRAFT','PENDING'))pp OUTER APPLY(SELECT SUM(i.Quantity-i.ReturnedQuantity)Qty FROM sales.SalesInvoiceItems i JOIN sales.SalesInvoices h ON h.InvoiceId=i.InvoiceId WHERE i.ProductId=p.ProductId AND h.WarehouseId=w.WarehouseId AND h.InvoiceDate>=DATEADD(day,-30,SYSUTCDATETIME()) AND h.Status IN('POSTED','PAID','PARTIAL'))v WHERE p.IsActive=1 AND p.IsDeleted=0 AND w.IsActive=1 AND ISNULL(s.Qty,0)+ISNULL(pp.Qty,0)<=p.ReorderLevel;COMMIT;END
GO
PRINT N'Creating Procedure [inventory].[ReorderSuggestion_List]...';


GO
CREATE   PROCEDURE inventory.ReorderSuggestion_List @WarehouseId uniqueidentifier=NULL,@CategoryId uniqueidentifier=NULL,@ProductId uniqueidentifier=NULL,@Search nvarchar(100)=NULL AS BEGIN EXEC inventory.RefreshStockControl;SELECT r.ReorderSuggestionId,r.ProductId,p.ProductCode,p.ProductName,r.WarehouseId,w.WarehouseName,'REORDER',r.CurrentStock,r.SuggestedQuantity,r.GeneratedOn,r.Status,CONCAT('Pending: ',r.PendingPurchase,', daily velocity: ',r.SalesVelocity)Detail FROM inventory.ReorderSuggestions r JOIN master.Products p ON p.ProductId=r.ProductId JOIN inventory.Warehouses w ON w.WarehouseId=r.WarehouseId WHERE(@WarehouseId IS NULL OR r.WarehouseId=@WarehouseId)AND(@CategoryId IS NULL OR p.CategoryId=@CategoryId)AND(@ProductId IS NULL OR r.ProductId=@ProductId)AND(@Search IS NULL OR p.ProductCode LIKE '%'+@Search+'%' OR p.ProductName LIKE '%'+@Search+'%')ORDER BY r.SuggestedQuantity DESC;END
GO
PRINT N'Creating Procedure [inventory].[StockAdjustment_List]...';


GO
CREATE   PROCEDURE inventory.StockAdjustment_List @Search nvarchar(100)=NULL,@WarehouseId uniqueidentifier=NULL,@From datetimeoffset=NULL,@To datetimeoffset=NULL,@PageNumber int=1,@PageSize int=20 AS BEGIN SET NOCOUNT ON;WITH q AS(SELECT a.StockAdjustmentId Id,a.AdjustmentNo Number,t.TransactionDate Date,CONCAT(a.AdjustmentType,' / ',a.ReasonCode) Type,a.ApprovalStatus Status,t.Remarks,SUM(ISNULL(i.Quantity,0)) TotalQuantity,COUNT(i.StockAdjustmentItemId)ItemCount FROM inventory.StockAdjustments a JOIN inventory.InventoryTransactions t ON t.TransactionId=a.TransactionId LEFT JOIN inventory.StockAdjustmentItems i ON i.StockAdjustmentId=a.StockAdjustmentId WHERE(@Search IS NULL OR a.AdjustmentNo LIKE '%'+@Search+'%' OR a.ReasonCode LIKE '%'+@Search+'%')AND(@WarehouseId IS NULL OR t.WarehouseId=@WarehouseId)AND(@From IS NULL OR t.TransactionDate>=@From)AND(@To IS NULL OR t.TransactionDate<=@To)GROUP BY a.StockAdjustmentId,a.AdjustmentNo,t.TransactionDate,a.AdjustmentType,a.ReasonCode,a.ApprovalStatus,t.Remarks)SELECT * FROM q ORDER BY Date DESC OFFSET (CASE WHEN @PageNumber<1 THEN 0 ELSE @PageNumber-1 END)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;SELECT COUNT(*) FROM inventory.StockAdjustments a JOIN inventory.InventoryTransactions t ON t.TransactionId=a.TransactionId WHERE(@Search IS NULL OR a.AdjustmentNo LIKE '%'+@Search+'%' OR a.ReasonCode LIKE '%'+@Search+'%')AND(@WarehouseId IS NULL OR t.WarehouseId=@WarehouseId)AND(@From IS NULL OR t.TransactionDate>=@From)AND(@To IS NULL OR t.TransactionDate<=@To);END
GO
PRINT N'Creating Procedure [inventory].[StockAdjustment_Post]...';


GO
CREATE PROCEDURE inventory.StockAdjustment_Post @WarehouseId uniqueidentifier,@AdjustmentType nvarchar(10),@ReasonCode nvarchar(50),@ApprovalStatus nvarchar(20),@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@CreatedBy nvarchar(256)=NULL AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY
DECLARE @id uniqueidentifier=NEWID(),@tx uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('ADJ-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff')),@sign decimal(18,4)=CASE WHEN @AdjustmentType='INCREASE' THEN 1 ELSE -1 END;
DECLARE @items table(ProductId uniqueidentifier,ZoneId uniqueidentifier NULL,BinId uniqueidentifier NULL,BatchNo nvarchar(100) NULL,SerialNo nvarchar(100) NULL,Quantity decimal(18,4),UnitCost decimal(18,4));INSERT @items SELECT ProductId,SourceZoneId,SourceBinId,BatchNo,SerialNo,Quantity,UnitCost FROM OPENJSON(@ItemsJson) WITH(ProductId uniqueidentifier '$.ProductId',SourceZoneId uniqueidentifier '$.SourceZoneId',SourceBinId uniqueidentifier '$.SourceBinId',BatchNo nvarchar(100) '$.BatchNo',SerialNo nvarchar(100) '$.SerialNo',Quantity decimal(18,4) '$.Quantity',UnitCost decimal(18,4) '$.UnitCost');IF NOT EXISTS(SELECT 1 FROM @items) THROW 51000,'At least one adjustment item is required.',1;
INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionDate,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy,CreatedOn)VALUES(@tx,@no,SYSUTCDATETIME(),CASE WHEN @AdjustmentType='INCREASE' THEN 'ADJUSTMENT_IN' ELSE 'ADJUSTMENT_OUT' END,'STOCK_ADJUSTMENT',@id,@WarehouseId,@Remarks,@CreatedBy,SYSUTCDATETIME());INSERT inventory.StockAdjustments(StockAdjustmentId,TransactionId,AdjustmentNo,AdjustmentType,ReasonCode,ApprovalStatus,ApprovedBy,ApprovedOn,CreatedOn)VALUES(@id,@tx,@no,@AdjustmentType,@ReasonCode,@ApprovalStatus,CASE WHEN @ApprovalStatus='APPROVED' THEN @CreatedBy END,CASE WHEN @ApprovalStatus='APPROVED' THEN SYSUTCDATETIME() END,SYSUTCDATETIME());INSERT inventory.StockAdjustmentItems(StockAdjustmentId,ProductId,ZoneId,BinId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @id,* FROM @items;
IF @ApprovalStatus='APPROVED' BEGIN IF @AdjustmentType='DECREASE' AND EXISTS(SELECT 1 FROM @items i OUTER APPLY(SELECT SUM(QuantityAvailable) q FROM inventory.InventoryBalances b WITH(UPDLOCK,HOLDLOCK) WHERE b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND (b.ZoneId=i.ZoneId OR b.ZoneId IS NULL AND i.ZoneId IS NULL) AND (b.BinId=i.BinId OR b.BinId IS NULL AND i.BinId IS NULL) AND (b.BatchNo=i.BatchNo OR b.BatchNo IS NULL AND i.BatchNo IS NULL) AND (b.SerialNo=i.SerialNo OR b.SerialNo IS NULL AND i.SerialNo IS NULL))b WHERE ISNULL(b.q,0)<i.Quantity) AND NOT EXISTS(SELECT 1 FROM inventory.InventorySettings WHERE NegativeStockAllowed=1) THROW 51001,'Insufficient available stock.',1;
INSERT inventory.InventoryBalances(ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,QuantityOnHand,QuantityReserved,AverageCost,LastPurchaseCost,LastUpdated,CreatedOn,CreatedBy)SELECT i.ProductId,@WarehouseId,i.ZoneId,i.BinId,i.BatchNo,i.SerialNo,0,0,i.UnitCost,i.UnitCost,SYSUTCDATETIME(),SYSUTCDATETIME(),@CreatedBy FROM @items i WHERE NOT EXISTS(SELECT 1 FROM inventory.InventoryBalances b WHERE b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,''));UPDATE b SET QuantityOnHand=b.QuantityOnHand+@sign*i.Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy FROM inventory.InventoryBalances b JOIN @items i ON b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'');
INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @tx,ProductId,BatchNo,SerialNo,Quantity,UnitCost FROM @items;INSERT inventory.StockMovementHistory(TransactionId,TransactionDetailId,MovementDate,MovementType,ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,Quantity,BalanceAfter,ReferenceType,ReferenceId,Remarks,CreatedBy)SELECT @tx,d.TransactionDetailId,SYSUTCDATETIME(),CASE WHEN @sign=1 THEN 'ADJUSTMENT_IN' ELSE 'ADJUSTMENT_OUT' END,d.ProductId,@WarehouseId,i.ZoneId,i.BinId,d.BatchNo,d.SerialNo,@sign*d.Quantity,b.QuantityOnHand,'STOCK_ADJUSTMENT',@id,@Remarks,@CreatedBy FROM inventory.InventoryTransactionDetails d JOIN @items i ON i.ProductId=d.ProductId AND ISNULL(i.BatchNo,'')=ISNULL(d.BatchNo,'') AND ISNULL(i.SerialNo,'')=ISNULL(d.SerialNo,'') JOIN inventory.InventoryBalances b ON b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') WHERE d.TransactionId=@tx;
IF OBJECT_ID('finance.PostStockAdjustment') IS NOT NULL EXEC finance.PostStockAdjustment @TransactionId=@tx,@CreatedBy=@CreatedBy;END
COMMIT;SELECT @id OperationId,@tx TransactionId,@no Number;END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
PRINT N'Creating Procedure [inventory].[StockMovementHistory_List]...';


GO
CREATE   PROCEDURE inventory.StockMovementHistory_List @WarehouseId uniqueidentifier=NULL,@ProductId uniqueidentifier=NULL,@From datetimeoffset=NULL,@To datetimeoffset=NULL,@Search nvarchar(100)=NULL,@PageNumber int=1,@PageSize int=20 AS BEGIN SET NOCOUNT ON;SELECT h.StockMovementHistoryId,h.MovementDate,h.MovementType,t.TransactionNo,h.ProductId,p.ProductCode,p.ProductName,h.WarehouseId,w.WarehouseName,h.ZoneId,h.BinId,h.Quantity,h.BalanceAfter,h.ReferenceType,h.Remarks,h.CreatedBy FROM inventory.StockMovementHistory h JOIN inventory.InventoryTransactions t ON t.TransactionId=h.TransactionId JOIN master.Products p ON p.ProductId=h.ProductId JOIN inventory.Warehouses w ON w.WarehouseId=h.WarehouseId WHERE(@WarehouseId IS NULL OR h.WarehouseId=@WarehouseId)AND(@ProductId IS NULL OR h.ProductId=@ProductId)AND(@From IS NULL OR h.MovementDate>=@From)AND(@To IS NULL OR h.MovementDate<=@To)AND(@Search IS NULL OR t.TransactionNo LIKE '%'+@Search+'%'OR p.ProductCode LIKE '%'+@Search+'%'OR p.ProductName LIKE '%'+@Search+'%')ORDER BY h.MovementDate DESC OFFSET(CASE WHEN @PageNumber<1 THEN 0 ELSE @PageNumber-1 END)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;SELECT COUNT(*) FROM inventory.StockMovementHistory h JOIN inventory.InventoryTransactions t ON t.TransactionId=h.TransactionId JOIN master.Products p ON p.ProductId=h.ProductId WHERE(@WarehouseId IS NULL OR h.WarehouseId=@WarehouseId)AND(@ProductId IS NULL OR h.ProductId=@ProductId)AND(@From IS NULL OR h.MovementDate>=@From)AND(@To IS NULL OR h.MovementDate<=@To)AND(@Search IS NULL OR t.TransactionNo LIKE '%'+@Search+'%'OR p.ProductCode LIKE '%'+@Search+'%'OR p.ProductName LIKE '%'+@Search+'%');END
GO
