CREATE   PROCEDURE inventory.StockTransfer_List @Search nvarchar(100)=NULL,@WarehouseId uniqueidentifier=NULL,@From datetimeoffset=NULL,@To datetimeoffset=NULL,@PageNumber int=1,@PageSize int=20 AS BEGIN SET NOCOUNT ON;WITH q AS(SELECT h.StockTransferId Id,h.TransferNo Number,h.TransferDate Date,'TRANSFER' Type,h.ApprovalStatus Status,h.Remarks,SUM(ISNULL(i.Quantity,0))TotalQuantity,COUNT(i.StockTransferItemId)ItemCount FROM inventory.StockTransfers h LEFT JOIN inventory.StockTransferItems i ON i.StockTransferId=h.StockTransferId WHERE(@Search IS NULL OR h.TransferNo LIKE '%'+@Search+'%')AND(@WarehouseId IS NULL OR h.SourceWarehouseId=@WarehouseId OR h.DestinationWarehouseId=@WarehouseId)AND(@From IS NULL OR h.TransferDate>=@From)AND(@To IS NULL OR h.TransferDate<=@To)GROUP BY h.StockTransferId,h.TransferNo,h.TransferDate,h.ApprovalStatus,h.Remarks)SELECT * FROM q ORDER BY Date DESC OFFSET (CASE WHEN @PageNumber<1 THEN 0 ELSE @PageNumber-1 END)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;SELECT COUNT(*) FROM inventory.StockTransfers h WHERE(@Search IS NULL OR h.TransferNo LIKE '%'+@Search+'%')AND(@WarehouseId IS NULL OR h.SourceWarehouseId=@WarehouseId OR h.DestinationWarehouseId=@WarehouseId)AND(@From IS NULL OR h.TransferDate>=@From)AND(@To IS NULL OR h.TransferDate<=@To);END
GO
PRINT N'Creating Procedure [inventory].[StockTransfer_Post]...';


GO
CREATE PROCEDURE inventory.StockTransfer_Post @SourceWarehouseId uniqueidentifier,@DestinationWarehouseId uniqueidentifier,@TransferDate datetimeoffset,@ApprovalStatus nvarchar(20),@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@CreatedBy nvarchar(256)=NULL AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY DECLARE @id uniqueidentifier=NEWID(),@out uniqueidentifier=NEWID(),@in uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('TRF-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff'));DECLARE @i table(ProductId uniqueidentifier,SourceZoneId uniqueidentifier,SourceBinId uniqueidentifier,DestinationZoneId uniqueidentifier,DestinationBinId uniqueidentifier,BatchNo nvarchar(100),SerialNo nvarchar(100),Quantity decimal(18,4),UnitCost decimal(18,4));INSERT @i SELECT * FROM OPENJSON(@ItemsJson) WITH(ProductId uniqueidentifier '$.ProductId',SourceZoneId uniqueidentifier '$.SourceZoneId',SourceBinId uniqueidentifier '$.SourceBinId',DestinationZoneId uniqueidentifier '$.DestinationZoneId',DestinationBinId uniqueidentifier '$.DestinationBinId',BatchNo nvarchar(100) '$.BatchNo',SerialNo nvarchar(100) '$.SerialNo',Quantity decimal(18,4) '$.Quantity',UnitCost decimal(18,4) '$.UnitCost');IF NOT EXISTS(SELECT 1 FROM @i)THROW 51000,'At least one transfer item is required.',1;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionDate,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@out,@no+'-OUT',@TransferDate,'TRANSFER_OUT','STOCK_TRANSFER',@id,@SourceWarehouseId,@Remarks,@CreatedBy),(@in,@no+'-IN',@TransferDate,'TRANSFER_IN','STOCK_TRANSFER',@id,@DestinationWarehouseId,@Remarks,@CreatedBy);INSERT inventory.StockTransfers(StockTransferId,TransferNo,SourceTransactionId,DestinationTransactionId,SourceWarehouseId,DestinationWarehouseId,ApprovalStatus,TransferDate,Remarks,CreatedBy,CreatedOn)VALUES(@id,@no,@out,@in,@SourceWarehouseId,@DestinationWarehouseId,CASE WHEN @ApprovalStatus='APPROVED' THEN 'COMPLETED' ELSE @ApprovalStatus END,@TransferDate,@Remarks,@CreatedBy,SYSUTCDATETIME());INSERT inventory.StockTransferItems(StockTransferId,ProductId,SourceZoneId,SourceBinId,DestinationZoneId,DestinationBinId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @id,* FROM @i;
IF @ApprovalStatus='APPROVED' BEGIN IF EXISTS(SELECT 1 FROM @i i OUTER APPLY(SELECT SUM(QuantityAvailable) q FROM inventory.InventoryBalances b WITH(UPDLOCK,HOLDLOCK) WHERE b.ProductId=i.ProductId AND b.WarehouseId=@SourceWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,''))b WHERE ISNULL(b.q,0)<i.Quantity) AND NOT EXISTS(SELECT 1 FROM inventory.InventorySettings WHERE NegativeStockAllowed=1)THROW 51001,'Insufficient stock for transfer.',1;UPDATE b SET QuantityOnHand=QuantityOnHand-i.Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy FROM inventory.InventoryBalances b JOIN @i i ON b.ProductId=i.ProductId AND b.WarehouseId=@SourceWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'');INSERT inventory.InventoryBalances(ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,QuantityOnHand,QuantityReserved,AverageCost,LastPurchaseCost,LastUpdated,CreatedOn,CreatedBy)SELECT ProductId,@DestinationWarehouseId,DestinationZoneId,DestinationBinId,BatchNo,SerialNo,0,0,UnitCost,UnitCost,SYSUTCDATETIME(),SYSUTCDATETIME(),@CreatedBy FROM @i i WHERE NOT EXISTS(SELECT 1 FROM inventory.InventoryBalances b WHERE b.ProductId=i.ProductId AND b.WarehouseId=@DestinationWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,''));UPDATE b SET QuantityOnHand=QuantityOnHand+i.Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy FROM inventory.InventoryBalances b JOIN @i i ON b.ProductId=i.ProductId AND b.WarehouseId=@DestinationWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'');
INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @out,ProductId,BatchNo,SerialNo,Quantity,UnitCost FROM @i UNION ALL SELECT @in,ProductId,BatchNo,SerialNo,Quantity,UnitCost FROM @i;INSERT inventory.StockMovementHistory(TransactionId,TransactionDetailId,MovementDate,MovementType,ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,Quantity,BalanceAfter,ReferenceType,ReferenceId,Remarks,CreatedBy)SELECT d.TransactionId,d.TransactionDetailId,@TransferDate,CASE WHEN d.TransactionId=@out THEN 'TRANSFER_OUT' ELSE 'TRANSFER_IN' END,d.ProductId,CASE WHEN d.TransactionId=@out THEN @SourceWarehouseId ELSE @DestinationWarehouseId END,CASE WHEN d.TransactionId=@out THEN i.SourceZoneId ELSE i.DestinationZoneId END,CASE WHEN d.TransactionId=@out THEN i.SourceBinId ELSE i.DestinationBinId END,d.BatchNo,d.SerialNo,CASE WHEN d.TransactionId=@out THEN -d.Quantity ELSE d.Quantity END,b.QuantityOnHand,'STOCK_TRANSFER',@id,@Remarks,@CreatedBy FROM inventory.InventoryTransactionDetails d JOIN @i i ON i.ProductId=d.ProductId AND ISNULL(i.BatchNo,'')=ISNULL(d.BatchNo,'') AND ISNULL(i.SerialNo,'')=ISNULL(d.SerialNo,'') LEFT JOIN inventory.InventoryBalances b ON b.ProductId=i.ProductId AND b.WarehouseId=CASE WHEN d.TransactionId=@out THEN @SourceWarehouseId ELSE @DestinationWarehouseId END AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(CASE WHEN d.TransactionId=@out THEN i.SourceZoneId ELSE i.DestinationZoneId END,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(CASE WHEN d.TransactionId=@out THEN i.SourceBinId ELSE i.DestinationBinId END,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'') WHERE d.TransactionId IN(@out,@in);END COMMIT;SELECT @id OperationId,@out TransactionId,@no Number;END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
PRINT N'Altering Procedure [inventory].[Inventory_Adjust]...';


GO
ALTER PROCEDURE [inventory].[Inventory_Adjust] @ProductId UNIQUEIDENTIFIER,@WarehouseId UNIQUEIDENTIFIER,@ZoneId UNIQUEIDENTIFIER=NULL,@BinId UNIQUEIDENTIFIER=NULL,@BatchNo NVARCHAR(100)=NULL,@SerialNo NVARCHAR(100)=NULL,@Quantity DECIMAL(18,4),@UnitCost DECIMAL(18,4),@AdjustmentType NVARCHAR(10),@ReasonCode NVARCHAR(50),@Remarks NVARCHAR(1000)=NULL,@CreatedBy NVARCHAR(256)=NULL
AS
BEGIN
 SET NOCOUNT ON;SET XACT_ABORT ON;IF @Quantity<=0 THROW 51000,'Quantity must be greater than zero.',1;IF @AdjustmentType NOT IN('INCREASE','DECREASE') THROW 51000,'Invalid adjustment type.',1;
 DECLARE @AllowNegative BIT=(SELECT TOP(1) NegativeStockAllowed FROM inventory.InventorySettings),@BalanceId UNIQUEIDENTIFIER,@OnHand DECIMAL(18,4),@Average DECIMAL(18,4),@TransactionId UNIQUEIDENTIFIER=NEWID(),@AdjustmentId UNIQUEIDENTIFIER=NEWID(),@No NVARCHAR(50)=CONCAT('ADJ-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20)));
 SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;
 SELECT @BalanceId=InventoryBalanceId,@OnHand=QuantityOnHand,@Average=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK) WHERE ProductId=@ProductId AND WarehouseId=@WarehouseId AND ((ZoneId=@ZoneId)OR(ZoneId IS NULL AND @ZoneId IS NULL)) AND ((BinId=@BinId)OR(BinId IS NULL AND @BinId IS NULL)) AND ((BatchNo=@BatchNo)OR(BatchNo IS NULL AND @BatchNo IS NULL)) AND ((SerialNo=@SerialNo)OR(SerialNo IS NULL AND @SerialNo IS NULL));
 IF @BalanceId IS NULL BEGIN SET @BalanceId=NEWID();SET @OnHand=0;SET @Average=0;INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,CreatedBy)VALUES(@BalanceId,@ProductId,@WarehouseId,@ZoneId,@BinId,@BatchNo,@SerialNo,@CreatedBy);END;
 IF @AdjustmentType='DECREASE' AND ISNULL(@AllowNegative,0)=0 AND @OnHand<@Quantity BEGIN ROLLBACK;THROW 51001,'Insufficient stock.',1;END;
 INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@TransactionId,@No,CASE WHEN @AdjustmentType='INCREASE'THEN'ADJUSTMENT_IN'ELSE'ADJUSTMENT_OUT'END,'STOCK_ADJUSTMENT',@AdjustmentId,@WarehouseId,@Remarks,@CreatedBy);
 INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,SerialNo,Quantity,UnitCost)VALUES(@TransactionId,@ProductId,@BatchNo,@SerialNo,@Quantity,@UnitCost);
 INSERT inventory.StockAdjustments(StockAdjustmentId,TransactionId,AdjustmentNo,AdjustmentType,ReasonCode,ApprovalStatus)VALUES(@AdjustmentId,@TransactionId,@No,@AdjustmentType,@ReasonCode,'PENDING');
 UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand+CASE WHEN @AdjustmentType='INCREASE'THEN @Quantity ELSE -@Quantity END,AverageCost=CASE WHEN @AdjustmentType='INCREASE' AND @OnHand+@Quantity>0 THEN ((@OnHand*@Average)+(@Quantity*@UnitCost))/(@OnHand+@Quantity) ELSE AverageCost END,LastPurchaseCost=CASE WHEN @AdjustmentType='INCREASE'THEN @UnitCost ELSE LastPurchaseCost END,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@BalanceId;
 INSERT inventory.InventoryValuation(ProductId,WarehouseId,ValuationMethod,Quantity,UnitCost)SELECT @ProductId,@WarehouseId,ISNULL((SELECT TOP(1)ValuationMethod FROM inventory.InventorySettings),'AVERAGE'),SUM(QuantityOnHand),CASE WHEN SUM(QuantityOnHand)=0 THEN 0 ELSE SUM(QuantityOnHand*AverageCost)/SUM(QuantityOnHand) END FROM inventory.InventoryBalances WHERE ProductId=@ProductId AND WarehouseId=@WarehouseId;
 EXEC finance.PostStockAdjustment @TransactionId=@TransactionId,@CreatedBy=@CreatedBy;COMMIT;SELECT @TransactionId TransactionId,@AdjustmentId StockAdjustmentId,@No TransactionNo;
END;
GO
PRINT N'Altering Procedure [purchase].[Purchase_AddPayment]...';


GO
ALTER   PROCEDURE purchase.Purchase_AddPayment @PurchaseInvoiceId UNIQUEIDENTIFIER,@MethodCode NVARCHAR(30),@Amount DECIMAL(18,2),@ReferenceNumber NVARCHAR(100)=NULL,@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @Amount<=0 THROW 51200,'Payment must be positive.',1;BEGIN TRAN;DECLARE @Method UNIQUEIDENTIFIER=(SELECT PaymentMethodId FROM sales.PaymentMethods WHERE MethodCode=@MethodCode AND IsActive=1),@Grand DECIMAL(18,2),@Paid DECIMAL(18,2),@PaymentId UNIQUEIDENTIFIER=NEWID();SELECT @Grand=GrandTotal,@Paid=PaidAmount FROM purchase.PurchaseInvoices WITH(UPDLOCK)WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND IsDeleted=0 AND Status NOT IN('CANCELLED','DRAFT');IF @Method IS NULL OR @Grand IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase or payment method not found.',1;END;IF @Paid+@Amount>@Grand BEGIN ROLLBACK;THROW 51200,'Payment exceeds outstanding balance.',1;END;INSERT purchase.PurchasePayments(PurchasePaymentId,PurchaseInvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)VALUES(@PaymentId,@PurchaseInvoiceId,@Method,@Amount,@ReferenceNumber,@CreatedBy);UPDATE purchase.PurchaseInvoices SET PaidAmount=PaidAmount+@Amount,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE PurchaseInvoiceId=@PurchaseInvoiceId;EXEC finance.PostPayment @Domain='PURCHASE',@PaymentId=@PaymentId,@CreatedBy=@CreatedBy;COMMIT;SELECT @PurchaseInvoiceId PurchaseInvoiceId,@Paid+@Amount PaidAmount,@Grand-@Paid-@Amount BalanceAmount;END
GO
PRINT N'Altering Procedure [purchase].[Purchase_Post]...';


GO
ALTER PROCEDURE [purchase].[Purchase_Post] @SupplierId UNIQUEIDENTIFIER,@SupplierInvoiceNo NVARCHAR(100)=NULL,@InvoiceDate DATETIMEOFFSET,@DueDate DATETIMEOFFSET=NULL,@WarehouseId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@ExpensesJson NVARCHAR(MAX)=NULL,@PaymentsJson NVARCHAR(MAX)=NULL,@BillDiscount DECIMAL(18,2)=0,@RoundOff DECIMAL(18,2)=0,@Remarks NVARCHAR(1000)=NULL,@Status NVARCHAR(20)='POSTED',@CreatedBy NVARCHAR(256)=NULL AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @Status NOT IN('DRAFT','POSTED')THROW 51200,'Invalid purchase status.',1;IF NOT EXISTS(SELECT 1 FROM purchase.Suppliers WHERE SupplierId=@SupplierId AND IsActive=1 AND IsDeleted=0)THROW 51200,'Active supplier is required.',1;IF NOT EXISTS(SELECT 1 FROM inventory.Warehouses WHERE WarehouseId=@WarehouseId AND IsActive=1 AND IsDeleted=0)THROW 51200,'Active warehouse is required.',1;IF ISJSON(@ItemsJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@ItemsJson))THROW 51200,'Purchase requires items.',1;
DECLARE @Id UNIQUEIDENTIFIER=NEWID(),@SeriesId UNIQUEIDENTIFIER,@Prefix NVARCHAR(20),@Next BIGINT,@Len INT,@No NVARCHAR(50),@Subtotal DECIMAL(18,2),@ItemDiscount DECIMAL(18,2),@Tax DECIMAL(18,2),@Expenses DECIMAL(18,2)=0,@Grand DECIMAL(18,2),@Paid DECIMAL(18,2)=0,@Tx UNIQUEIDENTIFIER=NEWID();SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;
SELECT TOP(1)@SeriesId=PurchaseSeriesId,@Prefix=Prefix,@Next=NextNumber,@Len=NumberLength FROM purchase.PurchaseSeries WITH(UPDLOCK,HOLDLOCK)WHERE IsDefault=1 AND IsActive=1;IF @SeriesId IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase series is not configured.',1;END;SET @No=CONCAT(@Prefix,'-',RIGHT(REPLICATE('0',@Len)+CONVERT(NVARCHAR(20),@Next),@Len));UPDATE purchase.PurchaseSeries SET NextNumber=NextNumber+1 WHERE PurchaseSeriesId=@SeriesId;
SELECT @Subtotal=SUM(Quantity*PurchasePrice),@ItemDiscount=SUM(CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*PurchasePrice*DiscountPercentage/100 END),@Tax=SUM((Quantity*PurchasePrice-CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*PurchasePrice*DiscountPercentage/100 END)*GSTPercentage/100)FROM OPENJSON(@ItemsJson)WITH(Quantity DECIMAL(18,4),PurchasePrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),GSTPercentage DECIMAL(5,2));IF ISJSON(@ExpensesJson)=1 SELECT @Expenses=ISNULL(SUM(Amount),0)FROM OPENJSON(@ExpensesJson)WITH(Amount DECIMAL(18,2));SET @Grand=ROUND(@Subtotal-@ItemDiscount-@BillDiscount+@Tax+@Expenses+@RoundOff,2);IF ISJSON(@PaymentsJson)=1 SELECT @Paid=ISNULL(SUM(Amount),0)FROM OPENJSON(@PaymentsJson)WITH(Amount DECIMAL(18,2));IF @Paid>@Grand BEGIN ROLLBACK;THROW 51200,'Payment exceeds purchase total.',1;END;
INSERT purchase.PurchaseInvoices(PurchaseInvoiceId,InvoiceNumber,SupplierId,SupplierInvoiceNo,InvoiceDate,DueDate,WarehouseId,Subtotal,DiscountAmount,TaxAmount,ExpenseAmount,RoundOff,GrandTotal,PaidAmount,Status,Remarks,CreatedBy)VALUES(@Id,@No,@SupplierId,@SupplierInvoiceNo,@InvoiceDate,@DueDate,@WarehouseId,@Subtotal,@ItemDiscount+@BillDiscount,@Tax,@Expenses,@RoundOff,@Grand,@Paid,@Status,@Remarks,@CreatedBy);IF @Status='POSTED'INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionDate,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@Tx,@No+'-STK',@InvoiceDate,'PURCHASE','PURCHASE_INVOICE',@Id,@WarehouseId,@Remarks,@CreatedBy);
DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT ProductId,Barcode,BatchNo,ExpiryDate,Quantity,FreeQuantity,PurchasePrice,MRP,SellingPrice,DiscountPercentage,DiscountAmount,GSTPercentage FROM OPENJSON(@ItemsJson)WITH(ProductId UNIQUEIDENTIFIER,Barcode NVARCHAR(100),BatchNo NVARCHAR(100),ExpiryDate DATE,Quantity DECIMAL(18,4),FreeQuantity DECIMAL(18,4),PurchasePrice DECIMAL(18,4),MRP DECIMAL(18,4),SellingPrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),GSTPercentage DECIMAL(5,2));DECLARE @Product UNIQUEIDENTIFIER,@Barcode NVARCHAR(100),@Batch NVARCHAR(100),@Expiry DATE,@Qty DECIMAL(18,4),@Free DECIMAL(18,4),@Price DECIMAL(18,4),@MRP DECIMAL(18,4),@Sell DECIMAL(18,4),@DPct DECIMAL(5,2),@Disc DECIMAL(18,2),@GSTPct DECIMAL(5,2),@GST DECIMAL(18,2),@Line DECIMAL(18,2),@Allocated DECIMAL(18,2),@Balance UNIQUEIDENTIFIER,@OldQty DECIMAL(18,4),@OldCost DECIMAL(18,4),@StockQty DECIMAL(18,4),@NewCost DECIMAL(18,4);OPEN c;FETCH NEXT FROM c INTO @Product,@Barcode,@Batch,@Expiry,@Qty,@Free,@Price,@MRP,@Sell,@DPct,@Disc,@GSTPct;WHILE @@FETCH_STATUS=0 BEGIN IF @Qty<=0 OR @Price<0 OR @MRP<@Sell OR NOT EXISTS(SELECT 1 FROM master.Products WHERE ProductId=@Product AND IsActive=1 AND IsDeleted=0)BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51200,'Invalid purchase item.',1;END;SET @Disc=CASE WHEN ISNULL(@Disc,0)>0 THEN @Disc ELSE @Qty*@Price*ISNULL(@DPct,0)/100 END;SET @GST=(@Qty*@Price-@Disc)*ISNULL(@GSTPct,0)/100;SET @Line=ROUND(@Qty*@Price-@Disc+@GST,2);SET @Allocated=CASE WHEN @Subtotal>0 THEN @Expenses*(@Qty*@Price)/@Subtotal ELSE 0 END;INSERT purchase.PurchaseInvoiceItems(PurchaseInvoiceId,ProductId,Barcode,BatchNo,ExpiryDate,Quantity,FreeQuantity,PurchasePrice,MRP,SellingPrice,DiscountPercentage,DiscountAmount,GSTPercentage,GSTAmount,AllocatedExpense,LineTotal)VALUES(@Id,@Product,@Barcode,NULLIF(@Batch,''),@Expiry,@Qty,ISNULL(@Free,0),@Price,@MRP,@Sell,ISNULL(@DPct,0),@Disc,ISNULL(@GSTPct,0),@GST,@Allocated,@Line);
IF @Status='POSTED'BEGIN SET @Balance=NULL;SET @OldQty=0;SET @OldCost=0;SET @StockQty=@Qty+ISNULL(@Free,0);SELECT @Balance=InventoryBalanceId,@OldQty=QuantityOnHand,@OldCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@Product AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND ISNULL(BatchNo,'')=ISNULL(@Batch,'') AND SerialNo IS NULL;IF @Balance IS NULL BEGIN SET @Balance=NEWID();SET @OldQty=0;SET @OldCost=0;INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,BatchNo,QuantityOnHand,AverageCost,LastPurchaseCost,CreatedBy)VALUES(@Balance,@Product,@WarehouseId,NULLIF(@Batch,''),0,0,@Price,@CreatedBy);END;SET @NewCost=CASE WHEN @OldQty+@StockQty=0 THEN @Price ELSE ((@OldQty*@OldCost)+(@Qty*@Price-@Disc+@Allocated))/(@OldQty+@StockQty) END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand+@StockQty,AverageCost=@NewCost,LastPurchaseCost=@Price,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@Balance;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,Quantity,UnitCost)VALUES(@Tx,@Product,NULLIF(@Batch,''),@StockQty,@NewCost);INSERT inventory.InventoryValuation(ProductId,WarehouseId,ValuationMethod,Quantity,UnitCost,ValuationDate)VALUES(@Product,@WarehouseId,'AVERAGE',@OldQty+@StockQty,@NewCost,@InvoiceDate);UPDATE master.Products SET PurchasePrice=@Price,MRP=@MRP,SellingPrice=@Sell,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE ProductId=@Product;END;FETCH NEXT FROM c INTO @Product,@Barcode,@Batch,@Expiry,@Qty,@Free,@Price,@MRP,@Sell,@DPct,@Disc,@GSTPct;END;CLOSE c;DEALLOCATE c;
IF ISJSON(@ExpensesJson)=1 INSERT purchase.PurchaseExpenses(PurchaseInvoiceId,ExpenseType,Description,Amount,IsTaxable)SELECT @Id,ExpenseType,Description,Amount,IsTaxable FROM OPENJSON(@ExpensesJson)WITH(ExpenseType NVARCHAR(50),Description NVARCHAR(250),Amount DECIMAL(18,2),IsTaxable BIT);IF ISJSON(@PaymentsJson)=1 INSERT purchase.PurchasePayments(PurchaseInvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)SELECT @Id,m.PaymentMethodId,j.Amount,j.ReferenceNumber,@CreatedBy FROM OPENJSON(@PaymentsJson)WITH(MethodCode NVARCHAR(30),Amount DECIMAL(18,2),ReferenceNumber NVARCHAR(100))j JOIN sales.PaymentMethods m ON m.MethodCode=j.MethodCode AND m.IsActive=1;EXEC finance.PostSource @SourceType='PURCHASE',@SourceId=@Id,@CreatedBy=@CreatedBy;COMMIT;SELECT @Id PurchaseInvoiceId,@No InvoiceNumber,@Grand GrandTotal,@Paid PaidAmount,@Grand-@Paid BalanceAmount,@Status Status;END;
GO
PRINT N'Altering Procedure [purchase].[Purchase_Return]...';


GO
ALTER PROCEDURE [purchase].[Purchase_Return] @PurchaseInvoiceId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@Reason NVARCHAR(250),@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF ISJSON(@ItemsJson)<>1 THROW 51200,'Return items are required.',1;DECLARE @Warehouse UNIQUEIDENTIFIER,@Tx UNIQUEIDENTIFIER=NEWID(),@ReturnNo NVARCHAR(50)=CONCAT('PRET-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),18))),@Adjustment DECIMAL(18,2)=0;SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;SELECT @Warehouse=WarehouseId FROM purchase.PurchaseInvoices WITH(UPDLOCK)WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND Status IN('POSTED','PARTIALLY_RETURNED');IF @Warehouse IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase is not returnable.',1;END;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@Tx,@ReturnNo+'-STK','RETURN','PURCHASE_RETURN',@PurchaseInvoiceId,@Warehouse,@Reason,@CreatedBy);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT PurchaseItemId,Quantity FROM OPENJSON(@ItemsJson)WITH(PurchaseItemId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4));DECLARE @Item UNIQUEIDENTIFIER,@Qty DECIMAL(18,4),@Product UNIQUEIDENTIFIER,@Batch NVARCHAR(100),@Purchased DECIMAL(18,4),@Returned DECIMAL(18,4),@Free DECIMAL(18,4),@Line DECIMAL(18,2),@Balance UNIQUEIDENTIFIER,@Available DECIMAL(18,4),@Cost DECIMAL(18,4);OPEN c;FETCH NEXT FROM c INTO @Item,@Qty;WHILE @@FETCH_STATUS=0 BEGIN SELECT @Product=ProductId,@Batch=BatchNo,@Purchased=Quantity,@Free=FreeQuantity,@Returned=ReturnedQuantity,@Line=LineTotal FROM purchase.PurchaseInvoiceItems WITH(UPDLOCK)WHERE PurchaseItemId=@Item AND PurchaseInvoiceId=@PurchaseInvoiceId;IF @Product IS NULL OR @Qty<=0 OR @Returned+@Qty>@Purchased+@Free BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51200,'Invalid return quantity.',1;END;SELECT @Balance=InventoryBalanceId,@Available=QuantityAvailable,@Cost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@Product AND WarehouseId=@Warehouse AND ZoneId IS NULL AND BinId IS NULL AND ISNULL(BatchNo,'')=ISNULL(@Batch,'') AND SerialNo IS NULL;IF @Balance IS NULL OR @Available<@Qty BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51201,'Insufficient stock for purchase return.',1;END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand-@Qty,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@Balance;UPDATE purchase.PurchaseInvoiceItems SET ReturnedQuantity=ReturnedQuantity+@Qty WHERE PurchaseItemId=@Item;DECLARE @Amount DECIMAL(18,2)=ROUND(@Line/NULLIF(@Purchased+@Free,0)*@Qty,2);SET @Adjustment+=@Amount;INSERT purchase.PurchaseReturns(ReturnNumber,PurchaseInvoiceId,PurchaseItemId,Quantity,AdjustmentAmount,Reason,CreatedBy)VALUES(CONCAT(@ReturnNo,'-',RIGHT(CONVERT(NVARCHAR(36),@Item),4)),@PurchaseInvoiceId,@Item,@Qty,@Amount,@Reason,@CreatedBy);INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,Quantity,UnitCost)VALUES(@Tx,@Product,@Batch,@Qty,@Cost);INSERT inventory.InventoryValuation(ProductId,WarehouseId,ValuationMethod,Quantity,UnitCost)SELECT @Product,@Warehouse,'AVERAGE',QuantityOnHand,AverageCost FROM inventory.InventoryBalances WHERE InventoryBalanceId=@Balance;FETCH NEXT FROM c INTO @Item,@Qty;END;CLOSE c;DEALLOCATE c;UPDATE purchase.PurchaseInvoices SET Status=CASE WHEN NOT EXISTS(SELECT 1 FROM purchase.PurchaseInvoiceItems WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND ReturnedQuantity<Quantity+FreeQuantity)THEN'RETURNED'ELSE'PARTIALLY_RETURNED'END,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE PurchaseInvoiceId=@PurchaseInvoiceId;EXEC finance.PostSource @SourceType='PURCHASE_RETURN',@SourceId=@PurchaseInvoiceId,@CreatedBy=@CreatedBy;COMMIT;SELECT @PurchaseInvoiceId PurchaseInvoiceId,@ReturnNo ReturnNumber,@Adjustment AdjustmentAmount,@Tx TransactionId;END;
GO
PRINT N'Altering Procedure [sales].[POS_AddPayment]...';


GO
ALTER   PROCEDURE sales.POS_AddPayment @InvoiceId UNIQUEIDENTIFIER,@MethodCode NVARCHAR(30),@Amount DECIMAL(18,2),@ReferenceNumber NVARCHAR(100)=NULL,@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @Amount<=0 THROW 51100,'Payment amount must be positive.',1;BEGIN TRAN;DECLARE @MethodId UNIQUEIDENTIFIER=(SELECT PaymentMethodId FROM sales.PaymentMethods WHERE MethodCode=@MethodCode AND IsActive=1),@Grand DECIMAL(18,2),@Paid DECIMAL(18,2),@ShiftId UNIQUEIDENTIFIER,@PaymentId UNIQUEIDENTIFIER=NEWID();SELECT @Grand=GrandTotal,@Paid=PaidAmount,@ShiftId=ShiftId FROM sales.SalesInvoices WITH(UPDLOCK)WHERE InvoiceId=@InvoiceId AND Status NOT IN('CANCELLED','VOID');IF @MethodId IS NULL OR @Grand IS NULL BEGIN ROLLBACK;THROW 51100,'Invoice or payment method not found.',1;END;IF @Paid+@Amount>@Grand BEGIN ROLLBACK;THROW 51100,'Payment exceeds balance.',1;END;INSERT sales.SalesPayments(PaymentId,InvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)VALUES(@PaymentId,@InvoiceId,@MethodId,@Amount,@ReferenceNumber,@CreatedBy);UPDATE sales.SalesInvoices SET PaidAmount=PaidAmount+@Amount,ModifiedOn=SYSUTCDATETIME()WHERE InvoiceId=@InvoiceId;IF @MethodCode='CASH'AND @ShiftId IS NOT NULL INSERT sales.CashDrawer(ShiftId,EntryType,Amount,ReferenceType,ReferenceId,CreatedBy)VALUES(@ShiftId,'SALE',@Amount,'SALES_INVOICE',@InvoiceId,@CreatedBy);EXEC finance.PostPayment @Domain='SALE',@PaymentId=@PaymentId,@CreatedBy=@CreatedBy;COMMIT;SELECT @InvoiceId InvoiceId,@Paid+@Amount PaidAmount,@Grand-@Paid-@Amount BalanceAmount;END
GO
PRINT N'Altering Procedure [sales].[POS_PostInvoice]...';


GO
ALTER PROCEDURE [sales].[POS_PostInvoice] @CounterId UNIQUEIDENTIFIER=NULL,@ShiftId UNIQUEIDENTIFIER=NULL,@CustomerId UNIQUEIDENTIFIER=NULL,@WarehouseId UNIQUEIDENTIFIER,@SalesPersonId UNIQUEIDENTIFIER=NULL,@ItemsJson NVARCHAR(MAX),@PaymentsJson NVARCHAR(MAX)=NULL,@BillDiscount DECIMAL(18,2)=0,@RoundOff DECIMAL(18,2)=0,@Remarks NVARCHAR(1000)=NULL,@Status NVARCHAR(20)='COMPLETED',@InterState BIT=0,@DiscountAuthorizedBy NVARCHAR(256)=NULL,@CreatedBy NVARCHAR(256)=NULL
AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @Status NOT IN('COMPLETED','HELD','SUSPENDED')THROW 51100,'Invalid invoice status.',1;IF ISJSON(@ItemsJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@ItemsJson))THROW 51100,'Invoice requires items.',1;
DECLARE @InvoiceId UNIQUEIDENTIFIER=NEWID(),@SeriesId UNIQUEIDENTIFIER,@Prefix NVARCHAR(20),@Next BIGINT,@Length INT,@InvoiceNumber NVARCHAR(50),@Subtotal DECIMAL(18,2)=0,@ItemDiscount DECIMAL(18,2)=0,@Tax DECIMAL(18,2)=0,@Grand DECIMAL(18,2),@Paid DECIMAL(18,2)=0,@InventoryTransactionId UNIQUEIDENTIFIER=NEWID(),@AllowNegative BIT=(SELECT TOP(1)NegativeStockAllowed FROM inventory.InventorySettings);
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;
SELECT TOP(1)@SeriesId=s.InvoiceSeriesId,@Prefix=s.Prefix,@Next=s.NextNumber,@Length=s.NumberLength FROM sales.InvoiceSeries s WITH(UPDLOCK,HOLDLOCK)LEFT JOIN sales.POSCounters c ON c.InvoiceSeriesId=s.InvoiceSeriesId WHERE s.IsActive=1 AND((@CounterId IS NOT NULL AND c.CounterId=@CounterId)OR(@CounterId IS NULL AND s.IsDefault=1))ORDER BY CASE WHEN @CounterId IS NOT NULL AND c.CounterId=@CounterId THEN 0 ELSE 1 END;IF @SeriesId IS NULL BEGIN ROLLBACK;THROW 51100,'Active invoice series not configured.',1;END;SET @InvoiceNumber=CONCAT(@Prefix,'-',RIGHT(REPLICATE('0',@Length)+CONVERT(NVARCHAR(20),@Next),@Length));UPDATE sales.InvoiceSeries SET NextNumber=NextNumber+1 WHERE InvoiceSeriesId=@SeriesId;
SELECT @Subtotal=SUM(Quantity*UnitPrice),@ItemDiscount=SUM(CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*UnitPrice*DiscountPercentage/100 END),@Tax=SUM(((Quantity*UnitPrice)-CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*UnitPrice*DiscountPercentage/100 END)*TaxPercentage/100)FROM OPENJSON(@ItemsJson)WITH(ProductId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4),UnitPrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),TaxPercentage DECIMAL(5,2));SET @Grand=ROUND(@Subtotal-@ItemDiscount-@BillDiscount+@Tax+@RoundOff,2);IF @Grand<0 BEGIN ROLLBACK;THROW 51100,'Invoice total cannot be negative.',1;END;IF ISJSON(@PaymentsJson)=1 SELECT @Paid=ISNULL(SUM(Amount),0)FROM OPENJSON(@PaymentsJson)WITH(Amount DECIMAL(18,2));IF @Paid>@Grand BEGIN ROLLBACK;THROW 51100,'Payment exceeds invoice total.',1;END;
INSERT sales.SalesInvoices(InvoiceId,InvoiceNumber,InvoiceDate,CounterId,ShiftId,CustomerId,WarehouseId,SalesPersonId,Subtotal,DiscountAmount,TaxAmount,RoundOff,GrandTotal,PaidAmount,Status,Remarks,CreatedBy)VALUES(@InvoiceId,@InvoiceNumber,SYSUTCDATETIME(),@CounterId,@ShiftId,@CustomerId,@WarehouseId,@SalesPersonId,@Subtotal,@ItemDiscount+@BillDiscount,@Tax,@RoundOff,@Grand,@Paid,@Status,@Remarks,@CreatedBy);IF @Status='COMPLETED' INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@InventoryTransactionId,@InvoiceNumber+'-STK','SALE','SALES_INVOICE',@InvoiceId,@WarehouseId,@Remarks,@CreatedBy);
DECLARE item_cursor CURSOR LOCAL FAST_FORWARD FOR SELECT ProductId,Barcode,Quantity,UnitPrice,DiscountPercentage,DiscountAmount,TaxPercentage FROM OPENJSON(@ItemsJson)WITH(ProductId UNIQUEIDENTIFIER,Barcode NVARCHAR(100),Quantity DECIMAL(18,4),UnitPrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),TaxPercentage DECIMAL(5,2));DECLARE @ProductId UNIQUEIDENTIFIER,@Barcode NVARCHAR(100),@Quantity DECIMAL(18,4),@UnitPrice DECIMAL(18,4),@DiscountPercentage DECIMAL(5,2),@DiscountAmount DECIMAL(18,2),@TaxPercentage DECIMAL(5,2),@Taxable DECIMAL(18,2),@TaxAmount DECIMAL(18,2),@LineTotal DECIMAL(18,2),@ItemId UNIQUEIDENTIFIER,@BalanceId UNIQUEIDENTIFIER,@Available DECIMAL(18,4),@AverageCost DECIMAL(18,4);
OPEN item_cursor;FETCH NEXT FROM item_cursor INTO @ProductId,@Barcode,@Quantity,@UnitPrice,@DiscountPercentage,@DiscountAmount,@TaxPercentage;WHILE @@FETCH_STATUS=0 BEGIN IF @Quantity<=0 OR @UnitPrice<0 BEGIN CLOSE item_cursor;DEALLOCATE item_cursor;ROLLBACK;THROW 51100,'Invalid invoice item quantity or price.',1;END;SET @DiscountAmount=CASE WHEN ISNULL(@DiscountAmount,0)>0 THEN @DiscountAmount ELSE @Quantity*@UnitPrice*ISNULL(@DiscountPercentage,0)/100 END;SET @Taxable=@Quantity*@UnitPrice-@DiscountAmount;SET @TaxAmount=@Taxable*ISNULL(@TaxPercentage,0)/100;SET @LineTotal=ROUND(@Taxable+@TaxAmount,2);SET @ItemId=NEWID();INSERT sales.SalesInvoiceItems(InvoiceItemId,InvoiceId,ProductId,Barcode,Quantity,UnitPrice,DiscountPercentage,DiscountAmount,TaxPercentage,TaxAmount,LineTotal)VALUES(@ItemId,@InvoiceId,@ProductId,@Barcode,@Quantity,@UnitPrice,ISNULL(@DiscountPercentage,0),@DiscountAmount,ISNULL(@TaxPercentage,0),@TaxAmount,@LineTotal);IF @DiscountAmount>0 INSERT sales.SalesDiscounts(InvoiceId,InvoiceItemId,DiscountType,DiscountMode,DiscountValue,DiscountAmount,AuthorizedBy)VALUES(@InvoiceId,@ItemId,'ITEM',CASE WHEN ISNULL(@DiscountPercentage,0)>0 THEN'PERCENTAGE'ELSE'FLAT'END,CASE WHEN ISNULL(@DiscountPercentage,0)>0 THEN @DiscountPercentage ELSE @DiscountAmount END,@DiscountAmount,@DiscountAuthorizedBy);IF @TaxAmount>0 BEGIN IF @InterState=1 INSERT sales.SalesTaxes(InvoiceId,InvoiceItemId,TaxType,TaxPercentage,TaxableAmount,TaxAmount)VALUES(@InvoiceId,@ItemId,'IGST',@TaxPercentage,@Taxable,@TaxAmount);ELSE INSERT sales.SalesTaxes(InvoiceId,InvoiceItemId,TaxType,TaxPercentage,TaxableAmount,TaxAmount)VALUES(@InvoiceId,@ItemId,'CGST',@TaxPercentage/2,@Taxable,@TaxAmount/2),(@InvoiceId,@ItemId,'SGST',@TaxPercentage/2,@Taxable,@TaxAmount/2);END;
IF @Status='COMPLETED' BEGIN SELECT @BalanceId=InventoryBalanceId,@Available=QuantityAvailable,@AverageCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@ProductId AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND BatchNo IS NULL AND SerialNo IS NULL;IF @BalanceId IS NULL OR(ISNULL(@AllowNegative,0)=0 AND @Available<@Quantity)BEGIN CLOSE item_cursor;DEALLOCATE item_cursor;ROLLBACK;THROW 51101,'Insufficient stock for invoice.',1;END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand-@Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@BalanceId;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,Quantity,UnitCost)VALUES(@InventoryTransactionId,@ProductId,@Quantity,ISNULL(@AverageCost,0));END;FETCH NEXT FROM item_cursor INTO @ProductId,@Barcode,@Quantity,@UnitPrice,@DiscountPercentage,@DiscountAmount,@TaxPercentage;END;CLOSE item_cursor;DEALLOCATE item_cursor;
IF @BillDiscount>0 INSERT sales.SalesDiscounts(InvoiceId,DiscountType,DiscountMode,DiscountValue,DiscountAmount,AuthorizedBy)VALUES(@InvoiceId,'BILL','FLAT',@BillDiscount,@BillDiscount,@DiscountAuthorizedBy);IF ISJSON(@PaymentsJson)=1 INSERT sales.SalesPayments(InvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)SELECT @InvoiceId,m.PaymentMethodId,j.Amount,j.ReferenceNumber,@CreatedBy FROM OPENJSON(@PaymentsJson)WITH(MethodCode NVARCHAR(30),Amount DECIMAL(18,2),ReferenceNumber NVARCHAR(100))j INNER JOIN sales.PaymentMethods m ON m.MethodCode=j.MethodCode AND m.IsActive=1;
IF @ShiftId IS NOT NULL AND EXISTS(SELECT 1 FROM OPENJSON(@PaymentsJson)j INNER JOIN sales.PaymentMethods m ON m.MethodCode=JSON_VALUE(j.value,'$.MethodCode')WHERE m.MethodCode='CASH')INSERT sales.CashDrawer(ShiftId,EntryType,Amount,ReferenceType,ReferenceId,CreatedBy)SELECT @ShiftId,'SALE',SUM(CONVERT(DECIMAL(18,2),JSON_VALUE(j.value,'$.Amount'))),'SALES_INVOICE',@InvoiceId,@CreatedBy FROM OPENJSON(@PaymentsJson)j WHERE JSON_VALUE(j.value,'$.MethodCode')='CASH';EXEC finance.PostSource @SourceType='SALE',@SourceId=@InvoiceId,@CreatedBy=@CreatedBy;COMMIT;SELECT @InvoiceId InvoiceId,@InvoiceNumber InvoiceNumber,@Grand GrandTotal,@Paid PaidAmount,@Status Status;END;
GO
PRINT N'Altering Procedure [sales].[POS_ReturnInvoice]...';


GO
ALTER PROCEDURE [sales].[POS_ReturnInvoice] @InvoiceId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@Reason NVARCHAR(250),@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF ISJSON(@ItemsJson)<>1 THROW 51100,'Return items are required.',1;DECLARE @WarehouseId UNIQUEIDENTIFIER,@ReturnTransactionId UNIQUEIDENTIFIER=NEWID(),@ReturnNo NVARCHAR(50)=CONCAT('RET-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20))),@Refund DECIMAL(18,2)=0;SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;SELECT @WarehouseId=WarehouseId FROM sales.SalesInvoices WITH(UPDLOCK)WHERE InvoiceId=@InvoiceId AND Status IN('COMPLETED','PARTIALLY_RETURNED');IF @WarehouseId IS NULL BEGIN ROLLBACK;THROW 51100,'Invoice is not returnable.',1;END;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@ReturnTransactionId,@ReturnNo+'-STK','RETURN','SALES_RETURN',@InvoiceId,@WarehouseId,@Reason,@CreatedBy);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT InvoiceItemId,Quantity FROM OPENJSON(@ItemsJson)WITH(InvoiceItemId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4));DECLARE @ItemId UNIQUEIDENTIFIER,@Qty DECIMAL(18,4),@ProductId UNIQUEIDENTIFIER,@Sold DECIMAL(18,4),@Returned DECIMAL(18,4),@LineTotal DECIMAL(18,2),@UnitCost DECIMAL(18,4),@BalanceId UNIQUEIDENTIFIER;OPEN c;FETCH NEXT FROM c INTO @ItemId,@Qty;WHILE @@FETCH_STATUS=0 BEGIN SELECT @ProductId=ProductId,@Sold=Quantity,@Returned=ReturnedQuantity,@LineTotal=LineTotal FROM sales.SalesInvoiceItems WITH(UPDLOCK)WHERE InvoiceItemId=@ItemId AND InvoiceId=@InvoiceId;IF @ProductId IS NULL OR @Qty<=0 OR @Returned+@Qty>@Sold BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51100,'Invalid return quantity.',1;END;SET @Refund=@Refund+(@LineTotal/@Sold*@Qty);UPDATE sales.SalesInvoiceItems SET ReturnedQuantity=ReturnedQuantity+@Qty WHERE InvoiceItemId=@ItemId;INSERT sales.SalesInvoiceReturns(ReturnNumber,InvoiceId,InvoiceItemId,Quantity,RefundAmount,Reason,CreatedBy)VALUES(CONCAT(@ReturnNo,'-',RIGHT(CONVERT(NVARCHAR(36),@ItemId),4)),@InvoiceId,@ItemId,@Qty,@LineTotal/@Sold*@Qty,@Reason,@CreatedBy);SELECT @BalanceId=InventoryBalanceId,@UnitCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@ProductId AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND BatchNo IS NULL AND SerialNo IS NULL;IF @BalanceId IS NULL BEGIN SET @BalanceId=NEWID();INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,CreatedBy)VALUES(@BalanceId,@ProductId,@WarehouseId,@CreatedBy);END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand+@Qty,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@BalanceId;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,Quantity,UnitCost)VALUES(@ReturnTransactionId,@ProductId,@Qty,ISNULL(@UnitCost,0));FETCH NEXT FROM c INTO @ItemId,@Qty;END;CLOSE c;DEALLOCATE c;UPDATE sales.SalesInvoices SET Status=CASE WHEN NOT EXISTS(SELECT 1 FROM sales.SalesInvoiceItems WHERE InvoiceId=@InvoiceId AND ReturnedQuantity<Quantity)THEN'RETURNED'ELSE'PARTIALLY_RETURNED'END,ModifiedOn=SYSUTCDATETIME()WHERE InvoiceId=@InvoiceId;EXEC finance.PostSource @SourceType='SALE_RETURN',@SourceId=@InvoiceId,@CreatedBy=@CreatedBy;COMMIT;SELECT @InvoiceId InvoiceId,@ReturnNo ReturnNumber,@Refund RefundAmount,@ReturnTransactionId TransactionId;END;
GO
