GO
CREATE   PROCEDURE dashboard.Inventory_Get AS BEGIN SET NOCOUNT ON;EXEC inventory.RefreshStockControl;SELECT ISNULL(SUM(QuantityOnHand*AverageCost),0)TotalInventoryValue,COUNT(DISTINCT CASE WHEN QuantityAvailable>0 AND QuantityAvailable<=p.ReorderLevel THEN b.ProductId END)LowStockItems,COUNT(DISTINCT CASE WHEN QuantityAvailable=0 THEN b.ProductId END)OutOfStockItems,COUNT(DISTINCT CASE WHEN QuantityAvailable<0 THEN b.ProductId END)NegativeStock,ISNULL((SELECT COUNT(*)FROM inventory.InventoryAlerts WHERE Status='ACTIVE'AND AlertType='EXPIRING_SOON'),0)ExpiringProducts,ISNULL((SELECT COUNT(*)FROM inventory.InventoryAlerts WHERE Status='ACTIVE'AND AlertType='EXPIRED_STOCK'),0)ExpiredProducts,ISNULL((SELECT COUNT(*)FROM inventory.ReorderSuggestions WHERE Status='OPEN'),0)ReorderRequired FROM inventory.InventoryBalances b JOIN master.Products p ON p.ProductId=b.ProductId;SELECT TOP(20)p.ProductCode Label,b.QuantityAvailable Value FROM inventory.InventoryBalances b JOIN master.Products p ON p.ProductId=b.ProductId WHERE b.QuantityAvailable<=p.ReorderLevel ORDER BY b.QuantityAvailable;END
GO
PRINT N'Creating Procedure [dashboard].[Notifications_Get]...';


GO
CREATE   PROCEDURE dashboard.Notifications_Get @Top int=50 AS BEGIN SET NOCOUNT ON;EXEC inventory.RefreshStockControl;EXEC finance.RefreshOutstanding;DELETE dashboard.DashboardNotifications WHERE ReferenceType IN('INVENTORY_ALERT','CUSTOMER_OUTSTANDING','SUPPLIER_OUTSTANDING')AND IsDismissed=0;INSERT dashboard.DashboardNotifications(NotificationType,Severity,Title,Message,ReferenceType,ReferenceId)SELECT AlertType,CASE WHEN AlertType IN('NEGATIVE_STOCK','EXPIRED_STOCK')THEN'CRITICAL'ELSE'WARNING'END,REPLACE(AlertType,'_',' '),Detail,'INVENTORY_ALERT',InventoryAlertId FROM inventory.InventoryAlerts WHERE Status='ACTIVE';INSERT dashboard.DashboardNotifications(NotificationType,Severity,Title,Message,ReferenceType,ReferenceId)SELECT'PENDING_COLLECTION','WARNING','Pending customer collection',CONCAT(InvoiceNumber,' outstanding ',OutstandingAmount),'CUSTOMER_OUTSTANDING',InvoiceId FROM finance.CustomerOutstanding WHERE OutstandingAmount>0;INSERT dashboard.DashboardNotifications(NotificationType,Severity,Title,Message,ReferenceType,ReferenceId)SELECT'PENDING_PAYMENT','WARNING','Pending supplier payment',CONCAT(InvoiceNumber,' outstanding ',OutstandingAmount),'SUPPLIER_OUTSTANDING',PurchaseInvoiceId FROM finance.SupplierOutstanding WHERE OutstandingAmount>0;SELECT TOP(@Top)DashboardNotificationId,NotificationType,Severity,Title,Message,ReferenceType,ReferenceId,IsRead,GeneratedOn FROM dashboard.DashboardNotifications WHERE IsDismissed=0 AND(ExpiresOn IS NULL OR ExpiresOn>SYSUTCDATETIME())ORDER BY CASE Severity WHEN'CRITICAL'THEN 1 WHEN'WARNING'THEN 2 ELSE 3 END,GeneratedOn DESC;END
