CREATE   PROCEDURE gst.GSTR1_Get @From datetimeoffset,@To datetimeoffset,@WarehouseId uniqueidentifier=NULL AS BEGIN SET NOCOUNT ON;EXEC gst.SyncTransactions;SELECT CASE WHEN IsB2B=1 THEN'B2B'ELSE'B2C'END SupplyType,GSTRate,COUNT(DISTINCT SourceId)InvoiceCount,SUM(TaxableAmount)TaxableAmount,SUM(CGSTAmount)CGSTAmount,SUM(SGSTAmount)SGSTAmount,SUM(IGSTAmount)IGSTAmount,SUM(CessAmount)CessAmount FROM gst.GSTTransactions WHERE SourceType='SALE'AND DocumentDate>=@From AND DocumentDate<@To AND(@WarehouseId IS NULL OR WarehouseId=@WarehouseId)GROUP BY IsB2B,GSTRate ORDER BY SupplyType,GSTRate;END
