GO
CREATE   PROCEDURE finance.Payment_Post @SupplierId uniqueidentifier,@PaymentType nvarchar(30),@PaymentDate datetimeoffset,@ReferenceNumber nvarchar(100)=NULL,@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@AllocationsJson nvarchar(max)=NULL,@CreatedBy nvarchar(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY DECLARE @id uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('PAY-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff')),@total decimal(18,2),@allocated decimal(18,2);DECLARE @items table(PaymentMode nvarchar(30),Amount decimal(18,2),ReferenceNumber nvarchar(100),ChequeNumber nvarchar(50),ChequeDate date,BankName nvarchar(150));INSERT @items SELECT * FROM OPENJSON(@ItemsJson)WITH(PaymentMode nvarchar(30)'$.PaymentMode',Amount decimal(18,2)'$.Amount',ReferenceNumber nvarchar(100)'$.ReferenceNumber',ChequeNumber nvarchar(50)'$.ChequeNumber',ChequeDate date'$.ChequeDate',BankName nvarchar(150)'$.BankName');DECLARE @alloc table(PurchaseInvoiceId uniqueidentifier,Amount decimal(18,2));INSERT @alloc SELECT * FROM OPENJSON(ISNULL(@AllocationsJson,'[]'))WITH(PurchaseInvoiceId uniqueidentifier'$.PurchaseInvoiceId',Amount decimal(18,2)'$.Amount');SELECT @total=SUM(Amount)FROM @items;SELECT @allocated=ISNULL(SUM(Amount),0)FROM @alloc;IF ISNULL(@total,0)<=0 OR @allocated>@total THROW 51330,'Payment totals or allocations are invalid.',1;IF EXISTS(SELECT 1 FROM @alloc a LEFT JOIN purchase.PurchaseInvoices i ON i.PurchaseInvoiceId=a.PurchaseInvoiceId AND i.SupplierId=@SupplierId WHERE i.PurchaseInvoiceId IS NULL OR a.Amount<=0 OR a.Amount>i.BalanceAmount)THROW 51331,'Payment allocation exceeds invoice outstanding or invoice is invalid.',1;INSERT finance.Payments(PaymentId,PaymentNumber,PaymentDate,SupplierId,PaymentType,TotalAmount,AllocatedAmount,ReferenceNumber,Remarks,CreatedBy)VALUES(@id,@no,@PaymentDate,@SupplierId,@PaymentType,@total,@allocated,@ReferenceNumber,@Remarks,@CreatedBy);INSERT finance.PaymentItems(PaymentId,PaymentModeId,Amount,ReferenceNumber,ChequeNumber,ChequeDate,BankName)SELECT @id,m.PaymentModeId,i.Amount,i.ReferenceNumber,i.ChequeNumber,i.ChequeDate,i.BankName FROM @items i JOIN finance.PaymentModes m ON m.ModeCode=i.PaymentMode AND m.IsActive=1;IF @@ROWCOUNT<>(SELECT COUNT(*)FROM @items)THROW 51332,'One or more payment modes are invalid.',1;INSERT finance.PaymentAllocation(PaymentId,PurchaseInvoiceId,AllocatedAmount,CreatedBy)SELECT @id,PurchaseInvoiceId,Amount,@CreatedBy FROM @alloc;UPDATE i SET PaidAmount=i.PaidAmount+a.Amount,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy FROM purchase.PurchaseInvoices i JOIN @alloc a ON a.PurchaseInvoiceId=i.PurchaseInvoiceId;DECLARE @mode nvarchar(30),@amount decimal(18,2),@itemref nvarchar(100),@journal uniqueidentifier,@jn nvarchar(50);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT PaymentMode,Amount,COALESCE(ReferenceNumber,@ReferenceNumber)FROM @items;OPEN c;FETCH NEXT FROM c INTO @mode,@amount,@itemref;WHILE @@FETCH_STATUS=0 BEGIN DECLARE @r table(Id uniqueidentifier,Number nvarchar(50));INSERT @r EXEC finance.PostPartyTransaction 'PAYMENT','SUPPLIER',@SupplierId,@mode,@amount,@PaymentDate,@itemref,@Remarks,@CreatedBy;SELECT TOP 1 @journal=Id,@jn=Number FROM @r;UPDATE TOP(1)finance.PaymentItems SET JournalEntryId=@journal WHERE PaymentId=@id AND JournalEntryId IS NULL AND Amount=@amount;DELETE @r;FETCH NEXT FROM c INTO @mode,@amount,@itemref;END CLOSE c;DEALLOCATE c;EXEC finance.RefreshOutstanding;COMMIT;SELECT @id DocumentId,@no DocumentNumber,@total TotalAmount,@allocated AllocatedAmount;END TRY BEGIN CATCH IF CURSOR_STATUS('local','c')>=0 BEGIN CLOSE c;DEALLOCATE c;END IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
