CREATE   PROCEDURE inventory.InventoryAlert_List @WarehouseId uniqueidentifier=NULL,@CategoryId uniqueidentifier=NULL,@ProductId uniqueidentifier=NULL,@Search nvarchar(100)=NULL,@Status nvarchar(30)=NULL AS BEGIN EXEC inventory.RefreshStockControl;SELECT a.InventoryAlertId,a.ProductId,p.ProductCode,p.ProductName,a.WarehouseId,w.WarehouseName,a.AlertType,a.CurrentQuantity,a.SuggestedQuantity,a.GeneratedOn,a.Status,a.Detail FROM inventory.InventoryAlerts a JOIN master.Products p ON p.ProductId=a.ProductId JOIN inventory.Warehouses w ON w.WarehouseId=a.WarehouseId WHERE a.Status='ACTIVE'AND(@WarehouseId IS NULL OR a.WarehouseId=@WarehouseId)AND(@CategoryId IS NULL OR p.CategoryId=@CategoryId)AND(@ProductId IS NULL OR a.ProductId=@ProductId)AND(@Status IS NULL OR a.AlertType=@Status)AND(@Search IS NULL OR p.ProductCode LIKE '%'+@Search+'%' OR p.ProductName LIKE '%'+@Search+'%')ORDER BY CASE a.AlertType WHEN 'NEGATIVE_STOCK'THEN 1 WHEN'OUT_OF_STOCK'THEN 2 WHEN'EXPIRED_STOCK'THEN 3 ELSE 4 END,a.GeneratedOn DESC;END
GO
