CREATE   PROCEDURE inventory.PhysicalVerification_Post @WarehouseId uniqueidentifier,@VerificationDate datetimeoffset,@ApprovalStatus nvarchar(20),@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@CreatedBy nvarchar(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY DECLARE @id uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('PHY-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff')),@adjust uniqueidentifier=NULL,@tx uniqueidentifier=NEWID();DECLARE @i table(ProductId uniqueidentifier,ZoneId uniqueidentifier,BinId uniqueidentifier,BatchNo nvarchar(100),SerialNo nvarchar(100),CountedQuantity decimal(18,4),UnitCost decimal(18,4),SystemQuantity decimal(18,4));INSERT @i(ProductId,ZoneId,BinId,BatchNo,SerialNo,CountedQuantity,UnitCost)SELECT * FROM OPENJSON(@ItemsJson) WITH(ProductId uniqueidentifier '$.ProductId',ZoneId uniqueidentifier '$.ZoneId',BinId uniqueidentifier '$.BinId',BatchNo nvarchar(100) '$.BatchNo',SerialNo nvarchar(100) '$.SerialNo',CountedQuantity decimal(18,4) '$.CountedQuantity',UnitCost decimal(18,4) '$.UnitCost');UPDATE i SET SystemQuantity=ISNULL((SELECT SUM(b.QuantityOnHand) FROM inventory.InventoryBalances b WITH(UPDLOCK,HOLDLOCK) WHERE b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'')),0) FROM @i i;INSERT inventory.PhysicalStockVerification(VerificationId,VerificationNo,VerificationDate,WarehouseId,ApprovalStatus,Remarks,ApprovedBy,ApprovedOn,CreatedBy)VALUES(@id,@no,@VerificationDate,@WarehouseId,@ApprovalStatus,@Remarks,CASE WHEN @ApprovalStatus='APPROVED' THEN @CreatedBy END,CASE WHEN @ApprovalStatus='APPROVED' THEN SYSUTCDATETIME() END,@CreatedBy);INSERT inventory.PhysicalStockVerificationItems(VerificationId,ProductId,ZoneId,BinId,BatchNo,SerialNo,SystemQuantity,CountedQuantity,UnitCost)SELECT @id,ProductId,ZoneId,BinId,BatchNo,SerialNo,SystemQuantity,CountedQuantity,UnitCost FROM @i;
IF @ApprovalStatus='APPROVED' AND EXISTS(SELECT 1 FROM @i WHERE CountedQuantity<>SystemQuantity) BEGIN DECLARE @json nvarchar(max)=(SELECT ProductId,ZoneId SourceZoneId,BinId SourceBinId,BatchNo,SerialNo,ABS(CountedQuantity-SystemQuantity) Quantity,UnitCost FROM @i WHERE CountedQuantity<>SystemQuantity FOR JSON PATH);DECLARE @result table(OperationId uniqueidentifier,TransactionId uniqueidentifier,Number nvarchar(50));IF NOT EXISTS(SELECT 1 FROM @i WHERE CountedQuantity<SystemQuantity) OR NOT EXISTS(SELECT 1 FROM @i WHERE CountedQuantity>SystemQuantity) BEGIN DECLARE @type nvarchar(10)=CASE WHEN EXISTS(SELECT 1 FROM @i WHERE CountedQuantity>SystemQuantity) THEN 'INCREASE' ELSE 'DECREASE' END;INSERT @result EXEC inventory.StockAdjustment_Post @WarehouseId,@type,'PHYSICAL_VERIFICATION','APPROVED',@Remarks,@json,@CreatedBy;SELECT TOP 1 @adjust=OperationId,@tx=TransactionId FROM @result;END ELSE BEGIN DECLARE @up nvarchar(max)=(SELECT ProductId,ZoneId SourceZoneId,BinId SourceBinId,BatchNo,SerialNo,CountedQuantity-SystemQuantity Quantity,UnitCost FROM @i WHERE CountedQuantity>SystemQuantity FOR JSON PATH),@down nvarchar(max)=(SELECT ProductId,ZoneId SourceZoneId,BinId SourceBinId,BatchNo,SerialNo,SystemQuantity-CountedQuantity Quantity,UnitCost FROM @i WHERE CountedQuantity<SystemQuantity FOR JSON PATH);INSERT @result EXEC inventory.StockAdjustment_Post @WarehouseId,'INCREASE','PHYSICAL_VERIFICATION','APPROVED',@Remarks,@up,@CreatedBy;INSERT @result EXEC inventory.StockAdjustment_Post @WarehouseId,'DECREASE','PHYSICAL_VERIFICATION','APPROVED',@Remarks,@down,@CreatedBy;SELECT TOP 1 @adjust=OperationId,@tx=TransactionId FROM @result;END UPDATE inventory.PhysicalStockVerification SET GeneratedAdjustmentId=@adjust WHERE VerificationId=@id;END COMMIT;SELECT @id OperationId,@tx TransactionId,@no Number;END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
