CREATE TABLE [#__checkStatus] (
    id           INT            IDENTITY (1, 1) PRIMARY KEY CLUSTERED,
    [Schema]     NVARCHAR (256),
    [Table]      NVARCHAR (256),
    [Constraint] NVARCHAR (256)
);

SET NOCOUNT ON;

DECLARE tableconstraintnames CURSOR LOCAL FORWARD_ONLY
    FOR SELECT SCHEMA_NAME([schema_id]),
               OBJECT_NAME([parent_object_id]),
               [name],
               0
        FROM   [sys].[objects]
        WHERE  [parent_object_id] IN (OBJECT_ID(N'finance.CustomerOutstanding'), OBJECT_ID(N'finance.SupplierOutstanding'), OBJECT_ID(N'dashboard.DashboardPreferences'), OBJECT_ID(N'dashboard.DashboardLayouts'), OBJECT_ID(N'gst.GSTTransactions'), OBJECT_ID(N'finance.CollectionFollowUp'), OBJECT_ID(N'finance.PaymentAllocation'), OBJECT_ID(N'finance.PaymentItems'), OBJECT_ID(N'finance.Payments'), OBJECT_ID(N'finance.ReceiptAllocation'), OBJECT_ID(N'finance.ReceiptItems'), OBJECT_ID(N'finance.Receipts'), OBJECT_ID(N'inventory.InventoryAlerts'), OBJECT_ID(N'inventory.PhysicalStockVerification'), OBJECT_ID(N'inventory.PhysicalStockVerificationItems'), OBJECT_ID(N'inventory.ReorderSuggestions'), OBJECT_ID(N'inventory.StockAdjustmentItems'), OBJECT_ID(N'inventory.StockMovementHistory'), OBJECT_ID(N'inventory.StockTransferItems'), OBJECT_ID(N'dashboard.DashboardNotifications'), OBJECT_ID(N'dashboard.DashboardWidgets'), OBJECT_ID(N'gst.GSTSettings'), OBJECT_ID(N'gst.GSTRates'), OBJECT_ID(N'finance.PaymentReminder'))
               AND [type] IN (N'F', N'C')
                   AND [object_id] IN (SELECT [object_id]
                                       FROM   [sys].[check_constraints]
                                       WHERE  [is_not_trusted] <> 0
                                              AND [is_disabled] = 0
                                       UNION
                                       SELECT [object_id]
                                       FROM   [sys].[foreign_keys]
                                       WHERE  [is_not_trusted] <> 0
                                              AND [is_disabled] = 0);

DECLARE @schemaname AS NVARCHAR (256);

DECLARE @tablename AS NVARCHAR (256);

DECLARE @checkname AS NVARCHAR (256);

DECLARE @is_not_trusted AS INT;

DECLARE @statement AS NVARCHAR (1024);

BEGIN TRY
    OPEN tableconstraintnames;
    FETCH tableconstraintnames INTO @schemaname, @tablename, @checkname, @is_not_trusted;
    WHILE @@fetch_status = 0
        BEGIN
            PRINT N'Checking constraint: ' + @checkname + N' [' + @schemaname + N'].[' + @tablename + N']';
            SET @statement = N'ALTER TABLE [' + @schemaname + N'].[' + @tablename + N'] WITH ' + CASE @is_not_trusted WHEN 0 THEN N'CHECK' ELSE N'NOCHECK' END + N' CHECK CONSTRAINT [' + @checkname + N']';
            BEGIN TRY
                EXECUTE [sp_executesql] @statement;
            END TRY
            BEGIN CATCH
                INSERT  [#__checkStatus] ([Schema], [Table], [Constraint])
                VALUES                  (@schemaname, @tablename, @checkname);
            END CATCH
            FETCH tableconstraintnames INTO @schemaname, @tablename, @checkname, @is_not_trusted;
        END
END TRY
BEGIN CATCH
    PRINT ERROR_MESSAGE();
END CATCH

IF CURSOR_STATUS(N'LOCAL', N'tableconstraintnames') >= 0
    CLOSE tableconstraintnames;

IF CURSOR_STATUS(N'LOCAL', N'tableconstraintnames') = -1
    DEALLOCATE tableconstraintnames;

SELECT N'Constraint verification failed:' + [Schema] + N'.' + [Table] + N',' + [Constraint]
FROM   [#__checkStatus];

IF @@ROWCOUNT > 0
    BEGIN
        DROP TABLE [#__checkStatus];
        RAISERROR (N'An error occurred while verifying constraints', 16, 127);
    END

SET NOCOUNT OFF;

DROP TABLE [#__checkStatus];


GO
PRINT N'Update complete.';


GO
SET NOEXEC OFF;
GO
